window.JASTROW_CHUNKS[1006]={"34912":{"h":"בַּרְסָם","r":"KRU03367","alt":[],"source":"krupnik","glosses":[{"text":"cattarrh of the head","label":""}],"html":"<p>נזלת cattarrh of the head  גיט׳ ס״ט ע״א: לברסם ליתי כי פסקתא דנישדור; חול׳ ק״ה ע״ב: משום דקשה לכרסם (לברסם).</p>","notation":[]},"34913":{"h":"ברסנה","r":"KRU03368","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ שביעי׳ ט׳ ל״ט ע״א: אילון דבית ברסנה (צ״ל כרסנא); ירוש׳ דמאי ג׳ כ״ג ע״ב: בר בר סנה. </p>","notation":["שם מקום","Source emendation: כַּרְסָנָה"]},"34914":{"h":"בֵּרֵץ","r":"KRU03369","alt":[],"source":"krupnik","glosses":[{"text":"to heap","label":"פיעל, 1"},{"text":"to cut through","label":"פיעל, 2"}],"html":"<p>פיעל, 1 מלא יותר על המדה to heap  מנח׳ פ״א מ״ב: איזה הוא היתר שקמצו מבורץ.\nפיעל, 2 חדר ועבר מקצה אל הקצה to cut through  תוס׳ כלאי׳ ג׳ י׳: חרוץ מבורץ.</p>","notation":[]},"34915":{"h":"בַּרְצוּץ","r":"KRU03371","alt":[],"source":"krupnik","glosses":[{"text":"to crown of the turban","label":""}],"html":"<p>צניף חבוש לראש to crown of the turban  תרג׳ יב״ע שמות ל״ט כ״ח (פארי המגבעות): וית ברציץ.</p>","notation":["ז׳"]},"34916":{"h":"בֵּי בַרְצִיתָא","r":"KRU03372","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  מו״ק ד׳ ע״ב: לבי ברציתא. </p>","notation":["שם מקום"]},"34917":{"h":"בָּרַק הִבְרִיק","r":"KRU03373","alt":[],"source":"krupnik","glosses":[{"text":"to cut through from end to end","label":"1"},{"text":"to be affected by lightning, to get blind","label":"2"}],"html":"<p>1 חדר ועבר מקצה אל הקצה to cut through from end to end  ירוש׳ כלא׳ ד׳ כ״ט ע״ד: חריץ מבריק ואינו מבריק.\n2 הוכה בסנורים ע״י ברק to be affected by lightning, to get blind  ב״מ פ״ו מ״ג: המוכר את החמור והבריקה.</p>","notation":["Marked biblical in source"]},"34918":{"h":"בְּרַק","r":"KRU03374","alt":[],"source":"krupnik","glosses":[{"text":"to shine","label":""},{"text":"to send forth lightning","label":""}],"html":"<p>הופיע to shine  ברכ׳ נ״ט ע״א: רעמים – ברקא תקיפא דבריק בעננא וכו׳. אַברֵק אפ׳ הבריק to send forth lightning  תרג׳ שני אסת׳ ג׳ ח׳: מבריקין עיניהין. </p>","notation":["פ״ע"]},"34919":{"h":"בְּנֵי בְרַק","r":"KRU03375","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  סנה׳ ל״ב ע״ב; אחר ר׳ עקיבא לבני ברק. </p>","notation":["שם מקום"]},"34920":{"h":"בַּרְקָא","r":"KRU03376","alt":[],"source":"krupnik","glosses":[{"text":"lightning","label":"1"},{"text":"euph: white cataract","label":"2"}],"html":"<p>1 ברק lightning  ברכ׳ נ״ט ע״א: ברקא יחידאה וברקא חיורא וכו׳.\n2 עורת (בלשון סגי נהור) euph: white cataract  בכו׳ ל״ח ע״ב: וסימנך ברקא.</p>","notation":[]},"34921":{"h":"בַּרְקָא⁴","r":"KRU03377","alt":[],"source":"krupnik","glosses":[{"text":"shining, white","label":""}],"html":"<p>לבן, בוצץ, shining, white  ירוש׳ ב״ב ח׳ ט״ז ע״ב: ארכבי אתרי ריכשי ברקי.</p>","notation":["ת׳"]},"34922":{"h":"בַּרְקָא²","r":"KRU03378","alt":[],"source":"krupnik","glosses":[{"text":"hair, thread","label":""}],"html":"<p>שער, חבל hair, thread  גיט׳ ס״ז: ע״א: שודרא ברקא; שבת ס״ז ע״א: נירא ברקא.</p>","notation":["ז׳"]},"34923":{"h":"בַּרְקָא³","r":"KRU03379","alt":[],"source":"krupnik","glosses":[{"text":"a kind of piazza","label":""}],"html":"<p>אכסדרה a kind of piazza  ב״ב ס״א ע״א: ברקא חלילא לא מזדבנא.</p>","notation":["ז׳"]},"34924":{"h":"בַּרְקַאי","r":"KRU03380","alt":[],"source":"krupnik","glosses":[{"text":"morning star","label":"1"},{"text":"name of a place","label":"2"}],"html":"<p>1 כוכב השחר morning star  יומא פ״ג מ״א: הרואה אומר ברקאי.\n2  name of a place  פסחי׳ נ״ז ע״א: כפר ברקאי.</p>","notation":[]},"34925":{"h":"בַּרְקוּרְיָאנֵי","r":"KRU03381","alt":[],"source":"krupnik","glosses":[{"text":"Herculiani, a cohort of pretorians, named after Diocletian (Heraclius)","label":""}],"html":"<p>שם גדודי חיל הרומאים Herculiani, a cohort of pretorians, named after Diocletian (Heraclius)  אסת״ר א׳ ג׳: יכולני ובר קוריאני (צ״ל יובייני וברקוריאני).</p>","notation":["ז״ר"]},"34926":{"h":"בְּרַקִּין","r":"KRU03382","alt":[],"source":"krupnik","glosses":[{"text":"breeches","label":""}],"html":"<p>breeches  ילמד׳ בראש׳: ברקין הנתונות וכו׳. </p>","notation":["ז״ר"]},"34927":{"h":"בַּרְקִירְיָא","r":"KRU03383","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ כלא׳ ט׳ ל״ב ע״ד: ר׳ ברקיריא ור׳ לעזר הוון מטיילין וכו׳.</p>","notation":[]},"34928":{"h":"בַּרְקִית","r":"KRU03384","alt":[],"source":"krupnik","glosses":[{"text":"cataract of the eye","label":""}],"html":"<p>מחלת העין cataract of the eye  שבת ע״ח ע״א: שכן כוחלין לברקית.</p>","notation":["נ׳"]},"34929":{"h":"בַּרְקָן","r":"KRU03385","alt":[],"source":"krupnik","glosses":[{"text":"smaragd","label":""}],"html":"<p>שם אבן טובה smaragd  תרג׳ יחז׳ כח י״ג וברקת – וברקן.</p>","notation":["נ׳"]},"34930":{"h":"בַּרְקָנַיָּא","r":"KRU03386","alt":[],"source":"krupnik","glosses":[{"text":"thistles","label":""}],"html":"<p>מין קוצים thistles  תרג׳ שופט׳ ח׳ ז׳ (ואת הברקנים): ברקניא.</p>","notation":["ז״ר"]},"34931":{"h":"בָּרֶקֶת","r":"KRU03387","alt":[],"source":"krupnik","glosses":[{"text":"morning star","label":""}],"html":"<p>כוכב השחר morning star  ירוש׳ ר״ה ב׳ נ״ז ע״ד: מהו בורקי ברקת.</p>","notation":["נ׳"]},"34932":{"h":"בַּרְקָתָא","r":"KRU03388","alt":[],"source":"krupnik","glosses":[{"text":"name of place","label":""}],"html":"<p>name of place  ע״ז ל״א ע״א: ושל ברקתא אסור. </p>","notation":["שם מקום"]},"34933":{"h":"בְּרַקְתִּי","r":"KRU03389","alt":[],"source":"krupnik","glosses":[{"text":"a cataract of the eye","label":""}],"html":"<p>ג׳, מחלת עינים a cataract of the eye  פסח׳ קי״א ע״ב: קשי לבריקתי (ערוך: לברקתי).</p>","notation":[]},"34934":{"h":"בָּרַר","r":"KRU03390","alt":[],"source":"krupnik","glosses":[{"text":"to make clear","label":"1"},{"text":"to choose","label":"2"}],"html":"<p>1 סילק את הספק to make clear  כתוב׳ מ״ו ע״א: ובוררין את הדבר כשמלה חדשה.\n2 בחר to choose  סנה׳ פ״ג מ״א: זה בורר לו אחד וזה בורר לו אחד.</p>","notation":["פ״י","Marked biblical in source"]},"34935":{"h":"בֵּרַר","r":"KRU03391","alt":["בֵּירַר"],"source":"krupnik","glosses":[{"text":"to ascertain","label":"פיעל 1"},{"text":"to select","label":"פיעל 2"},{"text":"to be decided","label":"הוּבְרָר הָפ׳,"},{"text":"to be confirmed","label":"נִתְבָּרֵר נתפ׳,"}],"html":"<p>פיעל 1 סילק את הספק to ascertain  סנה׳ כ״ג ע״ב: מחלוקת בשתי כתי עדים דר׳ מאיר סבר צריך לברר ורבנן סברי אין צריך לברר; תנחומא מצורע ה׳: אמרו לו תלמידיו רבי לא היית יודע הפסוק הזה א״ל הן אלא שבא זה ובררו בידי.\nפיעל 2 בחר, הבדיל to select  סנה׳ י״ז ע״א: מה עשה בירר ששה ששה.\nהוּבְרָר הָפ׳, נעשה ודאי to be decided  ביצה ד׳ ע״א: נשחטה הובררה דלאכילה עומדת.\nנִתְבָּרֵר נתפ׳, נתחזק to be confirmed  פסיק׳ דברי ירמי׳ קט״ו ע״ב: לא נתבררה נבואתן עד שאמר (צ״ל שעמד) ירמיה.</p>","notation":[]},"34936":{"h":"בְּרַר","r":"KRU03392","alt":[],"source":"krupnik","glosses":[{"text":"to select","label":""},{"text":"to be pure","label":""}],"html":"<p>בחר, הבדיל, to select  ירוש׳ שקל׳ ו׳ נ׳ ע״ב: נברור ארבע זוזי. אִתְבְּרִיר אתפ׳, היה בהיר to be pure  תרג׳ איוב כ״ה ה׳ (וכוכבים לא זכו בעיניו): לא אתברירו. </p>","notation":["פ״י"]},"34937":{"h":"בְּרָרָא","r":"KRU03393","alt":[],"source":"krupnik","glosses":[{"text":"pureness","label":"1"},{"text":"clearness, truth","label":"2"}],"html":"<p>1 טוהר pureness  ירוש׳ שקלי׳ ו׳ נ׳ ע״ב: עד דלא יקום על ברריה וכו׳.\n2 אמת clearness, truth  ירוש׳ יבמ׳ ח׳ ט׳ ע״ב: דו משים מילתא על בררא.</p>","notation":["ז׳"]},"34938":{"h":"בִּרְשָׁן","r":"KRU03395","alt":[],"source":"krupnik","glosses":[{"text":"naked, in ecstacy ?","label":""}],"html":"<p>ערום או משוגע naked, in ecstacy ?  תרג׳ שמ״א י״ט כ״ד (ויפל ערם): ונפל ברשן.</p>","notation":["ת׳"]},"34939":{"h":"בְּרַת","r":"KRU03397","alt":[],"source":"krupnik","glosses":[{"text":"daughter, young tree","label":""}],"html":"<p>בת, נצר daughter, young tree  ירוש׳ ב״מ ג׳ ח׳ ע״ג: אמר לחבריה אית לך ברת נוקבה א״ל אין; ויק״ר כ״ה: ברת פחין; ירוש׳ ב״ב ג׳ י״ג ע״ג: ברת שובעין חיורין.</p>","notation":["נ׳"]},"34940":{"h":"בְּרַת חוורן","r":"KRU03398","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ מו״ק פ׳ ע״ב: ר׳ חונייה דברת חוורן. </p>","notation":["שם מקום"]},"34941":{"h":"בְּרָתָא","r":"KRU03401","alt":[],"source":"krupnik","glosses":[{"text":"cypress or pine-tree","label":""}],"html":"<p>מין עץ, ברש cypress or pine-tree  ר״ה כ״ג ע״א: ברוש – ברתא; ירוש׳ פאה ח׳ כ׳ ע״א: אהן צררה סמך הדא ברתא.</p>","notation":["ז׳"]},"34942":{"h":"בַּרְתּוֹתָא","r":"KRU03402","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  אבות פ״ג מ״ח: רבי אלעזר איש ברתותא אומר תן לו משלו. </p>","notation":["שם מקום"]},"34943":{"h":"בִּשׁוּל","r":"KRU03413","alt":[],"source":"krupnik","glosses":[{"text":"ripening, cooking","label":""}],"html":"<p>גמילת הפרי, הרתחה באש ripening, cooking  חול׳ קט״ו ע״ב: אחד לאיסור אכילה ואחד לאיסור הנאה ואחד לאיסור בשול ועי׳ בִּישׁוּל.</p>","notation":["ז׳"]},"34944":{"h":"בָּשׂוּם","r":"KRU03416","alt":[],"source":"krupnik","glosses":[{"text":"delicate food","label":""}],"html":"<p>מטעמים delicate food  שהש״ר א׳ י״ב (עד שהמלך) ריח טוב מבשומי גן עדן.</p>","notation":["ז׳"]},"34945":{"h":"בְּשׂוֹרָה","r":"KRU03417","alt":[],"source":"krupnik","glosses":[{"text":"tidings","label":""}],"html":"<p>שמועה tidings  ברכ׳ פ״ט מ״ב: על בשורות טובות אומר ברוך הטוב והמטיב ועל בשורות רעות אומר ברוך דיין האמת.</p>","notation":["נ׳","Marked biblical in source"]},"34946":{"h":"בְּשׂוֹרְתָּא","r":"KRU03418","alt":[],"source":"krupnik","glosses":[{"text":"tidings","label":""}],"html":"<p>שמועה tidings  ב״ר פ״א סוף: בשורתא שמתה אמו; איכ״ר א׳ ה׳ (היו צריה): בשורתא טבתא איתבשרת.</p>","notation":["נ׳"]},"34947":{"h":"בְּשִׂירוּתָא","r":"KRU03421","alt":["בְּשִׂירוּתָה"],"source":"krupnik","glosses":[{"text":"good news","label":""}],"html":"<p>בשורה טובה good news  ירוש׳ חגי׳ ב׳ ע״ח ע״א: הדא כסא בשירותה בעייא מוליי; ירוש׳ ביצה ב׳ ס״א ע״ג: בשירותא בעייא מוליי.</p>","notation":[]},"34948":{"h":"בַּשְׁכַּר","r":"KRU03423","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  יומא י׳ ע״א: ואכד זה בשכר; שבת קל״ט ע״א: בני בשכר וכו׳ אינן בני תורה. </p>","notation":["שם מקום"]},"34949":{"h":"בָּשַׁל","r":"KRU03424","alt":[],"source":"krupnik","glosses":[{"text":"to mature","label":"בִּשֵּׁל פיעל,"},{"text":"to be boiled, to be ripe","label":"הִתְבַּשֵּׁל התפ׳,"}],"html":"<p>בִּשֵּׁל פיעל, הביא הפרי לגמר גידולו to mature  סנה׳ י״ב ע״א: אין לך קלה בכל ארץ ישראל לבשל פירותיה יותר מבעל שלישה.\nהִתְבַּשֵּׁל התפ׳, נגמל היטב או הורתח היטב, והיה ראוי לאכילה to be boiled, to be ripe  חול׳ צ״ח ע״ב: אין בשלה אלא שנתבשל עם האיל; תרומ׳ פ״י מי״א: כל המתבשלים זה עם זה מותרין.</p>","notation":["Marked biblical in source"]},"34950":{"h":"בְּשַׁל","r":"KRU03425","alt":[],"source":"krupnik","glosses":[{"text":"to ripen, to boil","label":""}],"html":"<p>גמל, הורתח באש והיה למאכל to ripen, to boil  תרג׳ יב״ע ברא׳ מ׳ י׳: (הבשילו): בשלו.</p>","notation":["פ״ע"]},"34951":{"h":"בַּשְׁלָא","r":"KRU03427","alt":[],"source":"krupnik","glosses":[{"text":"done, ripe","label":""}],"html":"<p>מורתח במים, נגמר done, ripe  תרג׳ יב״ע שמו׳ י״ב ט׳: כד בשלא בחמרא.</p>","notation":["ת׳"]},"34952":{"h":"בַּשָּׁלָא","r":"KRU03428","alt":[],"source":"krupnik","glosses":[{"text":"cook","label":""}],"html":"<p>טבח, מבשל cook  תרג׳ יחז׳ מ״ו כ״ד: (בית המבשלים): בשליא.</p>","notation":["ז׳"]},"34953":{"h":"בִּשְׁלָמָא … אֶלָּא","r":"KRU03430","alt":[],"source":"krupnik","glosses":[{"text":"granted, it is right, it would be right","label":""}],"html":"<p>ניחא לנו לדברי פלוני או אם הדבר כן, אבל.. granted, it is right, it would be right  פסח׳ כ״ד ע״ב: בשלמא אי אשמעינן פירא גופיה וכו׳ שפיר אלא … שם נ׳ ע״א: בשלמא למאן דאמר כל ביזה וכו׳ אלא …</p>","notation":[]},"34954":{"h":"בַּשָּׂם","r":"KRU03432","alt":[],"source":"krupnik","glosses":[{"text":"dealer in or manufacturer of spices","label":""}],"html":"<p>עושה או מוכר בשמים dealer in or manufacturer of spices  ברכ׳ נ״ג ע״א: הנכנס לחנותו של בשם והריח ריח.</p>","notation":["ז׳"]},"34955":{"h":"בַּשְׁקַר","r":"KRU03437","alt":[],"source":"krupnik","glosses":[{"text":"to search, to discover","label":""}],"html":"<p>חקר ומצא to search, to discover  תרג׳ תהל׳ מ״ד כ״ב (יחקר זאת): יבשקר דא; יבמ׳ ק״כ ע״א: חלף קמייהו ולא בשקרוה.</p>","notation":["פ״י"]},"34956":{"h":"בְּשַׂר","r":"KRU03439","alt":[],"source":"krupnik","glosses":[{"text":"to bring good tidings","label":"בַּשֵּׂר פַעֵל"},{"text":"to receive good tidings","label":"אִתְבַּשַּׂר אתפ׳,"}],"html":"<p>בַּשֵּׂר פַעֵל to bring good tidings  תרג׳ יב״ע ברא׳ מ״ט כ״א: הוא בשר. \nאִתְבַּשַּׂר אתפ׳, נתבשר to receive good tidings  תרג׳ רות א׳ ו׳ (כי שמעה): ארום אתבשרת.</p>","notation":["Source marks no qal form"]},"34957":{"h":"בָּשָׂר בָּשָׂר וְדָם","r":"KRU03440","alt":[],"source":"krupnik","glosses":[{"text":"mortal man","label":""}],"html":"<p>אדם, בן תמותה mortal man  ברכ׳ ל״ג ע״א: מלך בשר ודם שהיום כאן ומחר בקבר.</p>","notation":["Marked biblical in source"]},"34958":{"h":"בִּשְׂרָא","r":"KRU03441","alt":[],"source":"krupnik","glosses":[{"text":"flesh, meat, body","label":"1"},{"text":"mortal man","label":"2"}],"html":"<p>1 בשר, גוף flesh, meat, body  שבת ק״ג ע״ב: אמר רב האי תליא דבשרא שרי לטלטולי; תרג׳ ויק׳ י״ג ב׳ (בעור בשרו): במשך בשריה.\n2 אדם mortal man  תרג׳ ירמי׳ י״ז ה׳ (ושם בשר זרעו): וישוי בשרא רחצניה.</p>","notation":["ז׳"]},"34959":{"h":"בִּשְׂרָא²","r":"KRU03442","alt":[],"source":"krupnik","glosses":[{"text":"tidings","label":""}],"html":"<p>בשורה tidings  תרג׳ ירוש׳ ברא׳ כ״א ז׳: בשרא דבשר לאדוני.</p>","notation":["נ׳"]},"34960":{"h":"בִּשְׂרוּתָה","r":"KRU03443","alt":[],"source":"krupnik","glosses":[{"text":"good news","label":""}],"html":"<p>בשורה good news  ירוש׳ מעש״ש ה׳ נ״ו ע״ג: אמר ר׳ יצחק בר לעזר בשרותה בעיא מוליי.</p>","notation":["נ׳"]},"34961":{"h":"בְּשַׁשׁ","r":"KRU03445","alt":[],"source":"krupnik","glosses":[{"text":"seasoning, relishes","label":""}],"html":"<p>ליפתן, טפל למאכל seasoning, relishes  ברכ׳ מ׳ ע״א: לית דין צריך בשש; תרג׳ איוב ו׳ י׳ (תפל מבלי מלח): מידי בשש.</p>","notation":["ז׳"]},"34962":{"h":"בַּת בַּת אַבְרָהָם אָבִינוּ","r":"KRU03449","alt":[],"source":"krupnik","glosses":[{"text":"Jewess","label":""}],"html":"<p>יהודיה Jewess  גיט׳ פ״ט ע״א: לא הנחת בת לאברהם אבינו.</p>","notation":["Marked biblical in source"]},"34963":{"h":"בַּת אָבוֹת","r":"KRU03450","alt":[],"source":"krupnik","glosses":[{"text":"of noble descent","label":""}],"html":"<p>בת טובים of noble descent  במד״ר א׳: ראה ענייה יתומה בת אבות ביקש ליטול אותה.</p>","notation":[]},"34964":{"h":"בַּת אוֹר","r":"KRU03451","alt":[],"source":"krupnik","glosses":[{"text":"fuel","label":""}],"html":"<p>ראוי להסקה fuel  שבת כ״ה ע״ב: מכלל דבת אורו הוא.</p>","notation":[]},"34965":{"h":"בַּת אִיתְּרוּסֵי","r":"KRU03452","alt":[],"source":"krupnik","glosses":[{"text":"marriageable","label":""}],"html":"<p>ראויה לאירוסין ונשואין marriageable  גיט׳ מ״ג ע״א: ושפחה כנענית בת איתרוסי היא.</p>","notation":[]},"34966":{"h":"בַּת אַרְעָא","r":"KRU03453","alt":[],"source":"krupnik","glosses":[{"text":"sore on the foot","label":""}],"html":"<p>מכה תחת כף הרגל sore on the foot  שבת ס״ה ע״א: מאי צינית בת ארעא.</p>","notation":[]},"34967":{"h":"בַּת בּוּקְתָא","r":"KRU03454","alt":[],"source":"krupnik","glosses":[{"text":"neighbour","label":""}],"html":"<p>שכנה neighbour  יב׳ פ״ד ע״א: משום בת בוקתא דקבעי למיתני וכו׳ משום הכי קתני וכו׳.</p>","notation":[]},"34968":{"h":"בַּת בֵּירְתָא","r":"KRU03455","alt":[],"source":"krupnik","glosses":[{"text":"a little gutter fed by a well","label":""}],"html":"<p>חריץ קטן ובו מים הבאים מן המעין a little gutter fed by a well  חול׳ ק״ו ע״א: ובהא פליגי דמר סבר גזרינן בת בירתא אטו מנא וכו׳.</p>","notation":[]},"34969":{"h":"בַּת הָכִי","r":"KRU03456","alt":[],"source":"krupnik","glosses":[{"text":"of such condition","label":""}],"html":"<p>שיש לה סגולה זאת of such condition  סנה׳ כ״ה ע״ב: בהמה בת הכי היא.</p>","notation":[]},"34970":{"h":"בַּת חוֹרִין","r":"KRU03457","alt":[],"source":"krupnik","glosses":[{"text":"a free woman","label":"1"},{"text":"name of a demon","label":"2"}],"html":"<p>1 לא משועבדה a free woman  גיט׳ מ״א ע״ב: בת חורין.\n2 שם רוח רע name of a demon  שבת ק״ט ע״א: ר׳ נתן אומר בת חורין היא זו.</p>","notation":[]},"34971":{"h":"בַּת יוֹמָא","r":"KRU03458","alt":[],"source":"krupnik","glosses":[{"text":"of the same day","label":""}],"html":"<p>של אותו היום of the same day  ע״ז ע״ו ע״א: גזירה קדירה שאינה בת יומא משום קדירה בת יומא.</p>","notation":[]},"34972":{"h":"בַּת מַזְגָא חַמְרָא","r":"KRU03459","alt":[],"source":"krupnik","glosses":[{"text":"Little Wine-Mixer, name of a clean bird","label":""}],"html":"<p>שם עוף טהור Little Wine-Mixer, name of a clean bird  חול׳ ס״ג ע״א: בת מזגא חמרא.</p>","notation":[]},"34973":{"h":"בַּת מֶלֶךְ","r":"KRU03460","alt":[],"source":"krupnik","glosses":[{"text":"name of a demon","label":""}],"html":"<p>שם שידה name of a demon  שבת ק״ט ע״א: בת מלך.</p>","notation":[]},"34974":{"h":"בַּת נִירָא","r":"KRU03461","alt":[],"source":"krupnik","glosses":[{"text":"part of the weaver’s beam","label":""}],"html":"<p>חלק של עץ הארג part of the weaver’s beam  שבת ק״ה ע״א: אמר אביי תרתי בבתי (צ״ל בבת) נירא וחדא בנירא.</p>","notation":[]},"34975":{"h":"בַּת עַיִן","r":"KRU03462","alt":[],"source":"krupnik","glosses":[{"text":"eyeball","label":""}],"html":"<p>בבת עין eyeball  שמו״ר ל׳: חביבין ישראל כבת עין העליונה.</p>","notation":[]},"34976":{"h":"בַּת עֵינָא","r":"KRU03463","alt":[],"source":"krupnik","glosses":[{"text":"the hole in the millstone","label":""}],"html":"<p>נקב באמצע הרחים שהתבואה נופלת לתוכו the hole in the millstone  מו״ק י׳ ע״א: ר׳ יחיאל אמר בת עינא.</p>","notation":[]},"34977":{"h":"בּת קוֹל","r":"KRU03464","alt":[],"source":"krupnik","glosses":[{"text":"echo, reverberating sound","label":"1"},{"text":"Bathkol, divine voice","label":"2"}],"html":"<p>1 הד, קול הברה echo, reverberating sound  שמו״ר כ״ט סוף: כשאדם קורא לחבירו יש לקולו בת קול והקול שהיה יוצא מפי הקב״ה לא היה לקולו בת קול.\n2 קול לא טבעי השלוח מאת האלהים Bathkol, divine voice  סנה׳ י״א ע״א: שוב פעם אחת היו מסובין בעליה ביבנה ונתנה עליהם בת קול מן השמים; יומא ט׳ ע״ב: משמתו נביאים האחרוני׳ חגי זכרי׳ ומלאכי נסתלקה רוח הקודש מישראל ועדיין היו משתמשין בבת קול.</p>","notation":[]},"34978":{"h":"בַּת תִּיהָא","r":"KRU03465","alt":[],"source":"krupnik","glosses":[{"text":"the small bung-hole in the spicket","label":""}],"html":"<p>נקב במגופת חבית the small bung-hole in the spicket  ע״ז ס״ו ע״ב: האי בת תיהא נכרי בדישראל ש״ד.</p>","notation":[]},"34979":{"h":"בַּת בְּבַת אַחַת","r":"KRU03466","alt":[],"source":"krupnik","glosses":[{"text":"at once, simultaneously, suddenly","label":""}],"html":"<p>בפעם אחת, בלי הפסק, פתאום at once, simultaneously, suddenly  שבת מ׳ ע״א: לא כל גופו בבת אחת אלא אבר אבר; שמו״ר כ״ח: שהוא (האלהים) עושה את הכל בבת אחת ממית ומחיה בבת אחת וכו׳; תנחו׳ חקת א׳: אני מבערן מן העולם בבת אחת.</p>","notation":["Marked biblical in source"]},"34980":{"h":"בַּתְוָא","r":"KRU03469","alt":["בַּתְוָותָא"],"source":"krupnik","glosses":[{"text":"cuts in the valley or field","label":""}],"html":"<p>אמצע (הערוגה) cuts in the valley or field  שבת ק״י ע״ב: מבתוותא דמישרא (בערוך כן; בהוצ׳: מכבתותא דמישרי).</p>","notation":["ז׳"]},"34981":{"h":"בְּתוּלָה","r":"KRU03471","alt":[],"source":"krupnik","glosses":[{"text":"unbroken (soil) untrimmed (tree)","label":"1"},{"text":"the two posts supporting the beam in the wine-press","label":"2"},{"text":"Virgo, sign of the Zodiac","label":"3"}],"html":"<p>1 כל דבר שהוא עוד בבריתו הטבעית שעוד לא נשתמשו בו שום תשמיש unbroken (soil) untrimmed (tree)  תוס׳ שביעי׳ ג׳ י״ד – ט״ו: נמצאת אומר שלש בתולות הן בתולת אדם בתולות אדמה בתולת שקמה וכו׳.\n2 כל אחד משני הסדנים של עץ בבית הבד הקבועים בארץ והקורה יושבת בהם the two posts supporting the beam in the wine-press  ב״ב פ״ד מ״ה: המוכר את בית הבד מכר את הים ואת הממל ואת הבתולות.\n3 אחד מי״ב המזלות שבשמים Virgo, sign of the Zodiac  פסיק״ר כ׳: בתולה.</p>","notation":["Marked biblical in source"]},"34982":{"h":"בְּתוּלִין","r":"KRU03472","alt":[],"source":"krupnik","glosses":[{"text":"symptom of virginity","label":""}],"html":"<p>בתולים symptom of virginity  ירוש׳ כתוב׳ א׳ כ״ה ע״ב: אמר לון וכי בבתולין הדבר תלוי.</p>","notation":["ז״ר"]},"34983":{"h":"בְּתוּלְתָּא","r":"KRU03473","alt":[],"source":"krupnik","glosses":[{"text":"virgin","label":""}],"html":"<p>בתולה virgin  תרג׳ יב״ע ברא׳ כ״ד ט״ז (בתולה): בתולתא.</p>","notation":["נ׳"]},"34984":{"h":"בִּתְיָה","r":"KRU03474","alt":[],"source":"krupnik","glosses":[{"text":"Bithiah, daughter of Pharaoh","label":""}],"html":"<p>שם בת פרעה Bithiah, daughter of Pharaoh  סנה׳ ל״א ע״ב: שלחו ליה למר עוקבא לדזיו ליה כבר בתיה (משה רבינו) שלם.</p>","notation":["Marked biblical in source"]},"34985":{"h":"בְּתֵירָא","r":"KRU03475","alt":["בְּתֵירָה"],"source":"krupnik","glosses":[{"text":"a man’s name","label":""},{"text":"a scholarly family of Babylonian descent","label":""}],"html":"<p>שם איש a man’s name  יבמ׳ ק״ב ע״א: בן בתירא; פסח׳ ג׳ ע״ב: א״ל ר׳ יהודה בן בתירה מי קא ספי לך מאליה. בְּנֵי בְתֵירָה משפחת לומדים מבבל a scholarly family of Babylonian descent  פסח׳ ס״ו ע״א: הלכה זו נתעלמה מבני בתירה. </p>","notation":[]},"34986":{"h":"בָּתַר","r":"KRU03478","alt":[],"source":"krupnik","glosses":[{"text":"after, behind","label":""}],"html":"<p>אחר, אחרי after, behind  קדוש׳ ע״א ע״ב: זיל בתר שתיקתא; תרג׳ ברא׳ י׳ ל״ב (אחר המבול): בתר טובענא.</p>","notation":["תה״פ","Equivalent spelling: בַּאֲתַר"]},"34987":{"h":"בָּתַר דְ־","r":"KRU03479","alt":[],"source":"krupnik","glosses":[{"text":"after having","label":""}],"html":"<p>אחרי אשר after having  תרג׳ ברא׳ ה׳ ד׳ (אחרי הולידו): בתר ד־.</p>","notation":[]},"34988":{"h":"בַּתְרָא","r":"KRU03481","alt":["בַּתְרָאָה","בַּתְרַאי"],"source":"krupnik","glosses":[{"text":"the last, the latest","label":""}],"html":"<p>אחרון the last, the latest  גיט׳ מ״ז ע״א: יומא בתרא; נזיר נ״ו ע״ב: קמאי ובתראי; תרג׳ שמות ד׳ ח׳ (האות האחרון): אתא בתראה.</p>","notation":[]},"34989":{"h":"בְּתָרַיָּיא","r":"KRU03482","alt":[],"source":"krupnik","glosses":[{"text":"pieces","label":""}],"html":"<p>בתרים pieces  תרג׳ יב״ע בר׳ ט״ו י״ז (ברית בין הבתרים): ביני בתרייא.</p>","notation":["ז״ר"]},"34990":{"h":"בַּתְרַיְיתָא","r":"KRU03483","alt":[],"source":"krupnik","glosses":[{"text":"the last","label":""}],"html":"<p>אחרונה the last  ע״ז נ״א ע״א: א״ה בתרייתא מיהא תשתרי.</p>","notation":["ת׳"]},"34991":{"h":"בְּבָתְרֵיתָא","r":"KRU03484","alt":[],"source":"krupnik","glosses":[{"text":"in the last place, last","label":""}],"html":"<p>באחרונה in the last place, last  תרג׳ דבר׳ י״ג י׳ (באחרונה): בבתריתא.</p>","notation":["תה״פ"]},"34992":{"h":"בַּתֵּשׁ","r":"KRU03485","alt":[],"source":"krupnik","glosses":[{"text":"to urge, to beg persistently","label":"פַעל,"}],"html":"<p>פַעל, הפציר ב.. to urge, to beg persistently  שבוע׳ ל׳ ע״ב: בצורבא מרבנן מבתשינן; חול׳ ז׳ ע״ב: הוה קא מבתש ביה טובא.</p>","notation":[]},"34993":{"h":"גָאדִיל","r":"KRU03491","alt":[],"source":"krupnik","glosses":[{"text":"twister","label":""}],"html":"<p>עושה מעשה מקלעת twister  ב״ב קל״ג ע״ב: גאדיל כלילי דינאי מלכא.</p>","notation":["ז׳"]},"34994":{"h":"גָּאה גֵּאָה","r":"KRU03492","alt":[],"source":"krupnik","glosses":[{"text":"to exalt","label":"גֵּיאָה פיעל,"},{"text":"to show one’s self glorious, to boast, to be proud","label":"הִתְגָּאֶה התפ׳, נִתְגָּאֶה נתפ׳,"}],"html":"<p>גֵּיאָה פיעל, הגביה to exalt  ירוש׳ תענ׳ ג׳ ס״ד ע״א: אני אמרתי להשפילן ואת אמרת לגאותן.\nהִתְגָּאֶה התפ׳, נִתְגָּאֶה נתפ׳, התנשא, היה לבעל גאוה to show one’s self glorious, to boast, to be proud  חגי׳ י״ג ע״ב: לפי שמתגאה על גאים; שם ה׳ ע״ב: פרנס המתגאה על הצבור; ברכות ה׳ ע״ב: אמר הקב״ה לאחר שנתגאה זה קיבל עליו מלכות שמים.</p>","notation":["Marked biblical in source"]},"34995":{"h":"גַּאֲוָהגַּאֲוָוה","r":"KRU03494","alt":[],"source":"krupnik","glosses":[{"text":"glory","label":""}],"html":"<p>גדולה, התרוממות glory  חגי׳ ה׳ ע״ב: מפני גאוותה של מלכות שמים.</p>","notation":["נ׳","Marked biblical in source"]},"34996":{"h":"גַּאוָזָא","r":"KRU03495","alt":[],"source":"krupnik","glosses":[{"text":"division by lots","label":""}],"html":"<p>חלוקה בגורל division by lots  איכ״ר א׳ א׳ (חד מאתינס): תא נעביד גאוזין.</p>","notation":["ז׳"]},"34997":{"h":"גְּאוּלָה","r":"KRU03496","alt":[],"source":"krupnik","glosses":[{"text":"redemption","label":"1"},{"text":"delivery","label":"2"},{"text":"i>der Teil des Gebetes zwischen","label":"3"},{"text":"i>und dem Achtzehngebet","label":"3"},{"text":"the seventh benediction of the T’fillah","label":"4"}],"html":"<p>1 ישועה, ביאת המשיח redemption  מגי׳ ט״ו ע״א: כל האומר דבר בשם אומרו מביא גאולה לעולם.\n2 פדיון delivery  קדוש׳ ט״ו ע״ב: גאולת עצמו גאולת אחרים.\n3 חלק התפלה בין שמע לשמונה עשרה that section of the prayers between the שמע and the תפלה | &lt;i&gt;der Teil des Gebetes zwischen שמע &lt;i&gt;und dem Achtzehngebet ברכ׳ ט׳ ע״ב: סמך גאולה לתפלה.\n4 הברכה השביעית בתפלת שמ״ע the seventh benediction of the T’fillah  מגי׳ י״ז ע״ב: ומה ראו לומר גאולה בשביעית.</p>","notation":["נ׳","Marked biblical in source"]},"34998":{"h":"גְּאוּלְתָּא","r":"KRU03497","alt":[],"source":"krupnik","glosses":[{"text":"redemption","label":""}],"html":"<p>גאולה redemption  תרג׳ יב״ע במדבר כ״ה י״ב (בריתי שלום): גאולתא בסוף יומיא.</p>","notation":["נ׳"]},"34999":{"h":"גֵּאוּתָא","r":"KRU03499","alt":[],"source":"krupnik","glosses":[{"text":"haughtiness","label":""}],"html":"<p>גאוה, גאון haughtiness  תרג׳ משלי ה׳ י״ג (גאה וגאון): גאותא ורמותא.</p>","notation":["נ׳"]},"35000":{"h":"גְּאִי","r":"KRU03500","alt":[],"source":"krupnik","glosses":[{"text":"to be elated, to be exalted","label":""},{"text":"to grow","label":""},{"text":"to be proud, to be exalted","label":""}],"html":"<p>נתגדל, התרומם to be elated, to be exalted  תרג׳ ש״א ב׳ ה׳ (שבעים בלחם): וגאן בעותרא. אתְגָּאֵי אתפ׳, 1) התרומם, צמח to grow  תרג׳ איוב ח׳ י״א (היגאה גמא): האיפשר דאיתגאי גומיא. 2) התגאה, התנהג בגדלות to be proud, to be exalted  תרג׳ שמו׳ ט״ו א׳ (כי גאה גאה): אתגאי על גיותניא; תרג׳ שני אסת׳ ג׳ ג׳: מתגאה ומתרברב. </p>","notation":["פ״ע"]},"35001":{"h":"גָּאִיז","r":"KRU03501","alt":[],"source":"krupnik","glosses":[{"text":"to cut","label":""}],"html":"<p>הפסיק to cut  גיט׳ ס״ז ע״ב: זימנין דגאיז ליה לדיבוריה.</p>","notation":["פ״י"]},"35002":{"h":"גֵּאִים","r":"KRU03502","alt":[],"source":"krupnik","glosses":[{"text":"loftiness, excellence","label":""}],"html":"<p>התרוממות loftiness, excellence  חול׳ צ״ב ע״א: ובגפן שלשה שריגים וכו׳ אלו ג׳ שרי גאים היוצאין מישראל בכל דור ודור.</p>","notation":["ז״ר"]},"35003":{"h":"גָּאַל","r":"KRU03503","alt":[],"source":"krupnik","glosses":[{"text":"to be redeemed","label":"נִגְאַל נפ׳,"}],"html":"<p>נִגְאַל נפ׳, נפדה to be redeemed  ירוש׳ תענ׳ א׳ ס״ג ע״ד: מיד הן עושין תשובה והן נגאלין.</p>","notation":["Marked biblical in source"]},"35004":{"h":"גְּאַל","r":"KRU03504","alt":[],"source":"krupnik","glosses":[{"text":"to redeem, to ransom","label":""}],"html":"<p>פדה to redeem, to ransom  תרג׳ במדב׳ ל״ה י״ט (גואל הדם): גאל דמא.</p>","notation":["פ״י"]},"35005":{"h":"גְּאַם","r":"KRU03506","alt":[],"source":"krupnik","glosses":[{"text":"to make swallow","label":"גַּאֵם פַעל,"}],"html":"<p>גַּאֵם פַעל, בלע, הלעיט to make swallow  חול׳ קי״א ע״א: גאמו לשבא.</p>","notation":["פ״ע"]},"35006":{"h":"גַּב","r":"KRU03509","alt":[],"source":"krupnik","glosses":[{"text":"the exterior part of a thing","label":"1"}],"html":"<p>1 הצד החיצון בגוף the exterior part of a thing  סוכ׳ פ״ד מ״ד: על גב האיצטבא.</p>","notation":["Marked biblical in source"]},"35007":{"h":"גַּבַּיִים","r":"KRU03510","alt":["גַּבַּיִין"],"source":"krupnik","glosses":[{"text":"outsides of vessels","label":""},{"text":"on, upon, by the side of, on the basis, on the principle","label":""},{"text":"behind, in the back","label":""},{"text":"superintending","label":""},{"text":"to excel","label":""},{"text":"even on the top of) notwithstanding, although","label":""}],"html":"<p>אחורי הכלים outsides of vessels  כל׳ פכ״ה מ״ה: וחכ״א אין חולקין את הגביין (ובערוך עפ״י כ״י: גביים). עַל גַּב, עַל גַּבֵּי על, ממעל, אגב, בדרך, על ידי, בסבת־ on, upon, by the side of, on the basis, on the principle  אהל׳ פ״י מ״ד: ארובות זו על גב זו כו׳; שבת פ״ב ע״א: הנצרך לנקביו ואוכל דומה לתנור שהסיקוהו על גבי אפרו; נדה ס״ו ע״א: על גב הנהר; ירוש׳ חגיג׳ ב׳ ע״ה ע״א: חולין שנעשו על גב הקודש; שבת ל״ח ע״א: על גבי כירה; שבת פי״ב מ״ה: וכתב על גבי כתב; מו״ק ט״ז ע״ב: בשעה שהיה יושב בישיבה לא היה יושב על גבי כרים וכסתות אלא על גבי קרקע; יבמ׳ פ״א מ״ד: עושין טהרות אלו על גבי אלו. בְּגַב בפנים behind, in the back  ירוש׳ כתו׳ י״ב ל״ה ע״ב: דברים בגב (בבבלי קי״א ע״א: דברים בגו). עוֹמֵד עַל גַּבָּיו  שומר superintending  חול׳ ג׳ ע״א: עומד על גביו. עוֹלֶה עַל גַּבָּיו  עדיף ממנו to excel  אבות פ״ד מי״ג: וכתר שם טוב עולה על גביהן. אַף עַל גַּב, אַף עַל גַּב דְ… אף כי (even on the top of) notwithstanding, although  מגי׳ ג׳ ע״א: אף על גב דאיהו לא חזא וכו׳. </p>","notation":[]},"35008":{"h":"גַּבָּא","r":"KRU03511","alt":[],"source":"krupnik","glosses":[{"text":"back, upper side","label":""},{"text":"towards, with","label":""},{"text":"upon","label":""}],"html":"<p>1) גב, הצד העליון back, upper side  יבמ׳ ס״ג ע״ב: מקשטא ליה תכא ומהדרא ליה גבא; חול׳ מ״ז ע״ב: אגבא. 2) אצל, אל towards, with  ברכ׳ י׳ ע״א: ליתי גבאי; ירוש׳ נדר׳ ד׳ מ׳ ע״א: שלח ליה רבי תלת אגרין גבי ר׳ יצחק. אַגַּבָּא ממעל ל־ upon  חול׳ מ״ז ע״ב: אבל אגבא אפי׳ כטרפא דאסא טרפה. </p>","notation":["ז׳"]},"35009":{"h":"גְּבָא","r":"KRU03512","alt":[],"source":"krupnik","glosses":[{"text":"to collect, to tax","label":""},{"text":"to fine, to confiscate, to gain","label":""},{"text":"to be fined","label":""},{"text":"to esteem","label":""}],"html":"<p>1) דרש וקיבל חוב או מכס to collect, to tax  ב״מ י״ב ע״ב: נהי דלא גבי ממשעבדי מבני חרי מגבא גבי; דבה״י ב׳ ל״ו ג׳ (ויענש את הארץ): וגבא מן יתבי ארעא. אַגְבֵּי אַפע׳, ענש, תבע, הרויח to fine, to confiscate, to gain  כתוב׳ פ״ח ע״א: מגבי בי דמי שטרא; תרג׳ קהל׳ י״א ד׳ (וראה בעבים): לא מגבי אגר. אִתְגְּבִי אתפ׳, 1) נתבע (דמי עונשין) to be fined  תרג׳ שמו׳ כ״א כ״ב (ענש יענש): אתגבאה יתגבי. 2) הוקיר to esteem  תרג׳ משלי ח׳ י׳ (ודעת מחרוץ נבחר): וגבו לכון ידיעתא מן דהבא סנינא. </p>","notation":["פ״י"]},"35010":{"h":"גַּבָּאוּת","r":"KRU03513","alt":[],"source":"krupnik","glosses":[{"text":"office of collectorship","label":""}],"html":"<p>משרת הגבאי office of collectorship  תוס׳ דמ׳ ג׳: פירש מגבאותו.</p>","notation":["נ׳"]},"35011":{"h":"גַּבַּאי","r":"KRU03514","alt":[],"source":"krupnik","glosses":[{"text":"collector of taxes or charities, treasurer","label":""}],"html":"<p>גובה המכס, מקבל נדבות לצדקה collector of taxes or charities, treasurer  ב״ק צ״ד ע״א: הרועין והגבאין והמוכסין תשובתן קשה; פסח׳ י״ג ע״א: גבאי צדקה.</p>","notation":["ז׳"]},"35012":{"h":"גָּבַב","r":"KRU03515","alt":[],"source":"krupnik","glosses":[{"text":"to curve","label":""}],"html":"<p>כפף to curve  פסח׳ מ״ב ע״א: שלשה דברים מרבין הזבל וכופפין (בערוך: גובבין) את הקומה.</p>","notation":["פ״י"]},"35013":{"h":"גִּיבֵּב","r":"KRU03516","alt":[],"source":"krupnik","glosses":[{"text":"to heap up, to gather twigs, to rake, to pick up arguments","label":"פיעל,"}],"html":"<p>פיעל, אסף הרבה בלי סדר; פיטפט to heap up, to gather twigs, to rake, to pick up arguments  שביעי׳ פ״ט מ״ו: המגבב ביבש; יומ׳ ע״ו ע״א: עד מתי אתה מגבב דברים ומביא עלינו; ביצה פ״ד מ״ו: מגבב מן החצר ומדליק.</p>","notation":[]},"35014":{"h":"גְּבָבָא","r":"KRU03518","alt":[],"source":"krupnik","glosses":[{"text":"rakings heap","label":""}],"html":"<p>ענפים דקים יבשים, ערֵמה, rakings heap  שבת פ״ג מ״א: כירה שהסיקוה בקש ובגבבא; ברכ׳ ט׳ ע״ב: בין גבבא דעמרא חיורא לגבבא דעמרא דתכלתא.</p>","notation":["ז׳"]},"35015":{"h":"גְּבָבָה","r":"KRU03519","alt":[],"source":"krupnik","glosses":[{"text":"small stubble used as fuel","label":""}],"html":"<p>חתיכות קטנות של ענפים המשמשים להסקה small stubble used as fuel  פרה פ״ד מ״ג: שרפה (את פרת החטאת) שלא בעצים או בכל עצים אפילו בקש או בגבבה כשרה. ועי׳ גְּבָבָא.</p>","notation":["נ׳"]},"35016":{"h":"גַּבְבַיָּא","r":"KRU03520","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום בבבל name of a place  ירוש׳ קיד׳ ד׳ ס״ה ע״ד: גבביא.</p>","notation":[]},"35017":{"h":"גָּבָה","r":"KRU03522","alt":[],"source":"krupnik","glosses":[{"text":"to collect, to make one’s self paid","label":""},{"text":"to be collected, to be collectible, to be taxed","label":""},{"text":"to cause to be collected","label":""}],"html":"<p>תבע ולקח דמי פרעון, מכס או חוב to collect, to make one’s self paid  כתו׳ פ״ט מ״ט: הוציא גט ואין עמו כתובה גובה כתובתה; ב״מ פ״ה מי״א: שכיר יום גובה כל הלילה שכיר לילה גובה כל היום; ב״ר ה׳: מצא בע״ח לגבות שטר חובו. נִגְבָּה נפ׳, נשתלם to be collected, to be collectible, to be taxed  ב״ב פ״ט מ״ד: אבל השולח לחברו כדי יין וכדי שמן אין נגבין בב״ד מפני שהן גמילות חסדים; שם קמ״ו ע״א: סבלונות העשוין ליבלות אין נגבין ושאין עשוין לבלות נגבין; פסיק״ר י׳: לא היו נגבים וכו׳. הִגְבָּה הפע׳, גרם לגבות to cause to be collected  ב״מ ע״ז ע״ב: מהיכן מגביהו מן העידית; חלה פ״ג מ״א: מגבהת חלתה; יבמ׳ צ״ט ע״א: יש מוכר את אביו להגבות אמו כתובתה כיצד ישראל לקח עבד ושפחה וכו׳ נמצא זה מוכר את אביו להגבות לאמו כתובתה. </p>","notation":["פ״י"]},"35018":{"h":"גָּבַהּ","r":"KRU03523","alt":[],"source":"krupnik","glosses":[{"text":"to pick up, to raise","label":"הִגְבִּיהַּ הפע׳, 1"},{"text":"to take out","label":"הִגְבִּיהַּ הפע׳, 2"},{"text":"to clear away","label":"הִגְבִּיהַּ הפע׳, 3"},{"text":"to be raised","label":"הוּגְבַּהּ הָפע׳,"},{"text":"to be boastful","label":"הִתְגַּבֵּהַּ התפ׳,"}],"html":"<p>הִגְבִּיהַּ הפע׳, 1 נטל דבר ממקום שנפל והרימו למעלה to pick up, to raise  והרימו למעלה תרומ׳ פ״ה מ״ה: סאה תרומה שנפלה למאה הגביהה ונפלה למקום אחר; חול׳ פ״ב מ״ג: נפלה סבין (מידיו בשעת השחיטה) והגביהה כליו והגביהן.\nהִגְבִּיהַּ הפע׳, 2 הרים דבר מתוך דבר, הפריש to take out  ביצה פ״ה מ״ב: ולא מגביהין תרומה ומעשר.\nהִגְבִּיהַּ הפע׳, 3 הסיר מן to clear away  ביצה ב׳ ע״א: בית שמאי אומרים מגביהין מן השולחן עצמות וקליפין ובית הלל אומרים מסלק את הטבלא כולה ומנערה.\nהוּגְבַּהּ הָפע׳, נתרומם to be raised  סוטה מ״ז ע״ב: שפלים הוגבהו והגבוהים הושפלו.\nהִתְגַּבֵּהַּ התפ׳, התגאה to be boastful  תנחו׳ חקת א׳: התחיל מתגבה והולך (הוצ׳ בובר: מתגבר והולך).\nנִתְגַּבֵּהַּ נתפ׳, כנ״ל. במד״ר ו׳: מי גרם להם לבכורים שאבדו הכבוד הזה על שנתגבהו בעצמם. </p>","notation":["Marked biblical in source"]},"35019":{"h":"גְּבַה","r":"KRU03524","alt":[],"source":"krupnik","glosses":[{"text":"to be high, to rise","label":""},{"text":"to raise, to take up","label":""},{"text":"to be high, to grow proud","label":""},{"text":"to rise","label":""}],"html":"<p>התרומם to be high, to rise  חול׳ ז׳ ע״ב: גבה טורא בינייהו בכא רבי וכו׳; תהל׳ קל״א א׳ (לא גבה לבי): לא גְבַה לבי. אַגְּבַּהּ אַפע׳, הרים to raise, to take up  ב״מ ב׳ ע״ב: בהדי הדדי אגבהוה; תרג׳ דבהי״ב ל״ג י״ד (ויגביהה מאד): אגביה יתא. אּתְגַּבַּהּ אתפ׳, 1) היה רם וגבוה, התגאה to be high, to grow proud  תרג׳ קהל׳ א׳ י״ב; אתגבה ליביה; תרג׳ איוב ל״ה ה׳ (שחקים גבהו ממך): דאתגבהו מינך. 2) התרומם to rise  חול׳ קמ״א ע״ב: זיל טריף אקן דליתגבהו. </p>","notation":["פ״ע"]},"35020":{"h":"גַּבְהוּתָא","r":"KRU03525","alt":[],"source":"krupnik","glosses":[{"text":"pride","label":""}],"html":"<p>גאוה pride  תרג׳ דבהי״ב ל״ב כ״ו (בגבה לבו): בגבהותא דליביה.</p>","notation":["נ׳"]},"35021":{"h":"גָּבוֹהַּ","r":"KRU03526","alt":[],"source":"krupnik","glosses":[{"text":"high, exalted","label":""},{"text":"The Most High","label":""},{"text":"for the Lord, on the altar","label":""},{"text":"an expression alluding to Divinity","label":""},{"text":"an abnormally tall person","label":""}],"html":"<p>1) רם הקומה, רם המעלה high, exalted  סוטה ה׳ ע״א: מדת בשר ודם גבוה רואה את הגבוה ואין גבוה רואה את השפל. 2) כנוי לקדש (הקב״ה, המקדש, התורה) The Most High  ירוש׳ סנה׳ ז׳ כ״ה ע״ב: בעבודתה בעבודת גבוה. לַגָּבוֹהַּ למזבח for the Lord, on the altar  פסח׳ ג׳ ע״ב: אליה לגבוה סלקא. לְשׁוֹן גָּבוֹהַּ לשון הכתוב an expression alluding to Divinity  ירוש׳ נזיר א׳ נ״א ע״א: א״ר זעירה לשון גבוה הוא האומר לחרס ולא יזרח וגו׳. 3) איש רם הקומה מאד an abnormally tall person  בכור׳ מ״ה ע״ב: קפח תני ר׳ זביד גבוה; שם: אמר ר״ל גבוה לא ישא גבוהית שמא יצא מהן תורן. </p>","notation":["ת׳","Marked biblical in source"]},"35022":{"h":"גִּבוֹהִית","r":"KRU03527","alt":[],"source":"krupnik","glosses":[{"text":"an abnormally tall woman","label":""}],"html":"<p>אשה רמת הקומה מאד an abnormally tall woman  בכור׳ מ״ה ע״ב: גבוהית.</p>","notation":["נ׳"]},"35023":{"h":"גִּבּוּי","r":"KRU03528","alt":[],"source":"krupnik","glosses":[{"text":"collection","label":""}],"html":"<p>פעולת הגבייה collection  ב״ב ח׳ ע״ב: תמחוי נגבית בשלשה ומתחלקת בשלשה שגבויה וחלוקה שוים.</p>","notation":["ז׳"]},"35024":{"h":"גְּבוּל","r":"KRU03530","alt":[],"source":"krupnik","glosses":[{"text":"country, contrad. to the sanctuary and Jerusalem","label":"1"},{"text":"point of time, limit","label":"2"}],"html":"<p>1 כל ארץ ישראל חוץ מירושלים והמקדש country, contrad. to the sanctuary and Jerusalem  כתוב׳ כ״ד ע״ב: במה הייתם אוכלים בגולה בקדשי הגבול וכו׳; ר״ה ל׳ ע״א: תקיעת ר״ה ויובל דוחה את השבת בגבולין איש וביתו.\n2 זמן קצוב, הנקודה שממנו מתחיל או גומר דבר point of time, limit  כרית׳ כ״ה ע״א: א״ר ינאי גבול שמעתי בה ושכחתי; ע״ז כ״ד ע״ב: גבול יש לה פחותה מבת ג׳ שנים נעקרה וכ׳.</p>","notation":["Marked biblical in source"]},"35025":{"h":"גְּבוּל²","r":"KRU03531","alt":[],"source":"krupnik","glosses":[{"text":"name of a place, G’bul","label":""}],"html":"<p>שם מקום name of a place, G’bul  סוטה פ״ט מט״ו: ואנשי הגבול יסובבו מעיר לעיר ולא יתחננו; סנה׳ צ״ז ע״א: ואנשי גבול וכו׳.</p>","notation":[]},"35026":{"h":"גְּבוּלָאָה","r":"KRU03532","alt":["גְּבוּלָיָיא"],"source":"krupnik","glosses":[{"text":"of G’bul","label":""}],"html":"<p>ממחוז גבול of G’bul  קה״ר א׳ ד׳ (דור הולך): ר׳ יעקב גבולאה; ירוש׳ חלה ג׳ נ״ט ע״א: ר׳ יעקב גבולייא.</p>","notation":[]},"35027":{"h":"גבונתא","r":"KRU03533","alt":[],"source":"krupnik","glosses":[{"text":"bargain","label":""}],"html":"<p>מקח bargain  ירוש׳ תרומ׳ י׳ מ״ז ע״ב: ע״י עילה גבונת׳ איקלקלת.</p>","notation":["נ׳","Source emendation: זְבִינְתָּא"]},"35028":{"h":"גְּבוּרָא","r":"KRU03534","alt":["גְּבוּרְתָּא"],"source":"krupnik","glosses":[{"text":"strength, might","label":""}],"html":"<p>גבורה strength, might  תרג׳ ישעי׳ י״א ב׳ (רוח עצה וגבורה): רוח מלך וגבורא; תרג׳ דהי״ב י׳ י׳ (קטני עבה ממתני אבי): חלשותי תקיפא מן גבורתיה דאיבא.</p>","notation":[]},"35029":{"h":"גְּבוּרָה","r":"KRU03535","alt":[],"source":"krupnik","glosses":[{"text":"Divine Majesty, the Lord","label":"1"}],"html":"<p>1 הקב״ה Divine Majesty, the Lord  שבת פ״ז ע״א: ומה השיב משה לפני הגבורה.</p>","notation":["Marked biblical in source"]},"35030":{"h":"גבוריא","r":"KRU03536","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  מגי׳ י״ח ע״א: דרש ר׳ יהודה איש כפר גבוריא וכו׳.</p>","notation":[]},"35031":{"h":"גְּבוּשִׁין","r":"KRU03538","alt":[],"source":"krupnik","glosses":[{"text":"pile of stones","label":""}],"html":"<p>גל של אבנים pile of stones  תוס׳ אהל׳ י״ז ט׳: שגבשו בגבושין.</p>","notation":["ז״ר"]},"35032":{"h":"גִּבֵּחַ","r":"KRU03540","alt":[],"source":"krupnik","glosses":[{"text":"tall and slim","label":""}],"html":"<p>רם הקומה tall and slim  בכור׳ מ״ה ע״ב: גבוה (בערוך: גבח) לא ישא גבוהית וכו׳.</p>","notation":["ת׳"]},"35033":{"h":"גבח","r":"KRU03541","alt":[],"source":"krupnik","glosses":[{"text":"to shave a bald-pate","label":"גִּבַּח פיעל,"}],"html":"<p>גִּבַּח פיעל, עשה גבחת to shave a bald-pate  תוס׳ שבת ו׳ א׳: אלו דברים מדרכי האמורי המספר קומי והעושה בלורית והמגבח לגודגדין.</p>","notation":["Source marks no qal form"]},"35034":{"h":"גְּבִי","r":"KRU03542","alt":[],"source":"krupnik","glosses":[{"text":"pool","label":""}],"html":"<p>גבא, מקום מקוה מים pool  תוס׳ מקוא׳ א׳ ג׳: גבי שנפל לתוכו יין שמן ודבש.</p>","notation":["ז׳"]},"35035":{"h":"גַּבְיָא","r":"KRU03545","alt":[],"source":"krupnik","glosses":[{"text":"tall and slim","label":"1"},{"text":"excellent","label":"2"}],"html":"<p>1 גבוה tall and slim  תרג׳ יב״ע ויק׳ כ״ב כ״ב (עורת או שבור או חרוץ): דסמי ודתביר או דגביא.\n2 נבחר excellent  תרג׳ משלי ח׳ י״ט (כסף נבחר): מן סימא גביא.</p>","notation":["ת׳"]},"35036":{"h":"גַּבְיָא²","r":"KRU03546","alt":[],"source":"krupnik","glosses":[{"text":"name of a plant","label":""}],"html":"<p>שם צמח name of a plant  שבת קי״א ע״א: גביא גילא.</p>","notation":["נ׳"]},"35037":{"h":"גְּבִיהָא","r":"KRU03548","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ע״ז כ״ב ע״א: גביהא מבי כתיל. </p>","notation":["שם איש"]},"35038":{"h":"גַּבָּיוּת","r":"KRU03549","alt":[],"source":"krupnik","glosses":[{"text":"collectorship","label":""}],"html":"<p>פקודת הגבאי collectorship  ירוש׳ דמ׳ ב׳ כ״ג ע״א: יצא מגבייתו (צ״ל מגביותו) הרי הוא כחבר.</p>","notation":["נ׳"]},"35039":{"h":"גְּבִיחַ","r":"KRU03551","alt":[],"source":"krupnik","glosses":[{"text":"extremely tall","label":""}],"html":"<p>גדול ביותר extremely tall  תרג׳ ירוש׳ ב׳ ויקר׳ כ״א כ׳ (או גבן או דק): או דגביח או דנניס.</p>","notation":["ז׳"]},"35040":{"h":"גַּבְיָין","r":"KRU03553","alt":[],"source":"krupnik","glosses":[{"text":"an excellent man","label":""}],"html":"<p>איש מצוין an excellent man  תרג׳ משלי כ״א ה׳ (חרוץ): מחשבתא דגביין.</p>","notation":["ז׳"]},"35041":{"h":"גַּבְיַית","r":"KRU03554","alt":[],"source":"krupnik","glosses":[{"text":"name of a person","label":""}],"html":"<p>שם עצם פרטי name of a person  פסיק״ר כ״ט: אבוקה בן גביית.</p>","notation":[]},"35042":{"h":"גְּבִיל","r":"KRU03555","alt":[],"source":"krupnik","glosses":[{"text":"a mush of flour and water","label":""}],"html":"<p>בלילת מים וקמח a mush of flour and water  בר׳ ל״ז ע״ב: גביל מרתח.</p>","notation":["ז׳"]},"35043":{"h":"גְּבִילָה","r":"KRU03556","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":"1"}],"html":"<p>1  a man’s name  ירוש׳ נזי׳ ז׳ נ״ו ע״א: גבילה אחוי דר׳ בא.\n2 עי׳ נְבֵילָה. ירוש׳ בכורים ב׳ ס״ה ע״א: קרנה של גבילה (צ״ל נבילה). </p>","notation":[]},"35044":{"h":"גְּבִין","r":"KRU03557","alt":[],"source":"krupnik","glosses":[{"text":"hump-backed","label":""}],"html":"<p>בעל חטוטרת hump-backed  תרג׳ ויקר׳ כ״א כ׳ (גבן): גבין.</p>","notation":[]},"35045":{"h":"גָּבִין","r":"KRU03558","alt":[],"source":"krupnik","glosses":[{"text":"eye-brow","label":""}],"html":"<p>השערות שממעל לעפעפים eye-brow  בכור׳ מ״ג ע״ב: אין לו גבינין או אין לו אלא גבין אחד.</p>","notation":["ז׳"]},"35046":{"h":"גְּבִינָא²","r":"KRU03560","alt":[],"source":"krupnik","glosses":[{"text":"eye-lash","label":"2"}],"html":"<p>1 עי׳ גָּבִין. תרג׳ יב״ע ויק׳ כ״א כ׳ (גבן): דגביני שכבן. \n2 עפעפים eye-lash  ב״ק קי״ז ע״א: רב יוחנן גברא סבא הוה ומסרחי גביניה אמר להו דלי לי עיני (בכ״י מינכן: דלי לי גביני).</p>","notation":[]},"35047":{"h":"גְּבִינִי","r":"KRU03561","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  תמי׳ פ״ג מ״ח: גביני כרוז; קה״ר ד׳ ח׳ (יש אחד): גביני בן חרסון. </p>","notation":["שם איש"]},"35048":{"h":"גְּבִינְתָּה","r":"KRU03562","alt":[],"source":"krupnik","glosses":[{"text":"the camels) hump","label":""}],"html":"<p>חטוטרת (the camels) hump  ירוש׳ שבת ה׳ ז׳ ע״ב: כהדא כיפה דהיא משויא גבינתה.</p>","notation":["נ׳"]},"35049":{"h":"גְּבִיעָא","r":"KRU03563","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name G’ebiah (hump-backed)","label":""}],"html":"<p>(בעל חטוטרת) a man’s name G’ebiah (hump-backed)  ב״ר ס״א: גביהא (בערוך: גביעא) בן פסיסה.</p>","notation":["שם איש"]},"35050":{"h":"גְּבִיעָה","r":"KRU03564","alt":[],"source":"krupnik","glosses":[{"text":"hump","label":"1"},{"text":"name of a (hump-backed) man","label":"2"}],"html":"<p>1 חטוטרת hump  ב״ר ס״א: אני משוה לך גביעתך.\n2 שם איש (בעל חטוטרת) name of a (hump-backed) man  שם: א״ל גביעה בן קוסם.</p>","notation":["נ׳"]},"35051":{"h":"גְּבִירָה","r":"KRU03565","alt":[],"source":"krupnik","glosses":[{"text":"mistress","label":""}],"html":"<p>אשה שיש לה שפחה mistress  סוטה י״ב ע״ב: אמרו לה (השפחות לבת פרעה) גבירתנו מנהגו של עולם וכו׳; שמו״ר א׳: שלא יאמרו בני גבירות תחלה ובני השפחות אחרונה.</p>","notation":["Marked biblical in source"]},"35052":{"h":"גָּבַל","r":"KRU03566","alt":[],"source":"krupnik","glosses":[{"text":"to knead, to stamp","label":""}],"html":"<p>שם מים בקמח או עפר, לש to knead, to stamp  שבת פכ״ה מ״ג: נותנין מים למורסין אבל לא גובלין; תוס׳ מעש״ר ג׳ י״ג: שאינו גובל עיסתו בטהרה.</p>","notation":["פ״י"]},"35053":{"h":"גִּיבֵּל","r":"KRU03567","alt":[],"source":"krupnik","glosses":[{"text":"to be kneaded","label":"הִתְגַּבֵּל התפ׳,"}],"html":"<p>פיעל, כנ״ל. תעני׳ י׳ ע״א: לאדם שמגבל את הגבינה. \nהִתְגַּבֵּל התפ׳, נלוש to be kneaded  תעני׳ י״ט ע״ב: אם יש לו מים רבים אינן כלין והטיט אינו מתגבל יפה.</p>","notation":[]},"35054":{"h":"גְּבַל","r":"KRU03568","alt":[],"source":"krupnik","glosses":[{"text":"to grow","label":"2"}],"html":"<p>1 עי׳ גָּבַל. גיט׳ ס״ט ע״א: וניגבול בדובשא. \n2  to grow  חול׳ ס״ז ע״ב: מיניה קא גבלי.</p>","notation":[]},"35055":{"h":"גַּבֵּל","r":"KRU03569","alt":[],"source":"krupnik","glosses":[{"text":"to be kneaded","label":""}],"html":"<p>עי׳ גִּיבֵּל. ב״מ ס״ט ע״א: גביל לתורא גביל לתורי. אִתְגַּבֵּל, אִיגַּבֵּל,  אתפ׳, נלוש to be kneaded  ויק״ר ו׳: איגבלון בלישה. </p>","notation":["פַעל"]},"35056":{"h":"גַּבָּל","r":"KRU03570","alt":[],"source":"krupnik","glosses":[{"text":"kneader, baker","label":""}],"html":"<p>האיש הלש, נחתום kneader, baker  כתוב׳ ע״ב ע״א: פלוני גבל תיקן לי את העיסה; פסחי׳ ל״ד ע״א: אבא שאול גבל של בית רבי היה.</p>","notation":["ז׳"]},"35057":{"h":"גְּבַל²","r":"KRU03571","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  תרג׳ ירוש׳ דהי״א א׳ ל״ח (ובני שעיר): בנוי דגבל.</p>","notation":[]},"35058":{"h":"גַּבְלָא","r":"KRU03572","alt":[],"source":"krupnik","glosses":[{"text":"Highland, a district South of Jerusalem (Gabla)","label":"1"},{"text":"name of a town","label":"2"}],"html":"<p>1 שם ארץ מישור בראשי ההרים Highland, a district South of Jerusalem (Gabla)  תרג׳ ירוש׳ דבר׳ ל״ג ב׳ (הופיע מהר פארן): טורא דגבלא.\n2 שם עיר name of a town  כתוב׳ קי״ב ע״א: איקלע לגבלא.</p>","notation":[]},"35059":{"h":"גַּבָּלָא","r":"KRU03573","alt":[],"source":"krupnik","glosses":[{"text":"one that mixes fodder","label":""}],"html":"<p>מי שאומנתו לגבל one that mixes fodder  שבת קנ״ו ע״א; גבלא דבי נשיאה.</p>","notation":["ז׳"]},"35060":{"h":"גַּבְלוּל","r":"KRU03574","alt":[],"source":"krupnik","glosses":[{"text":"a roll of dough","label":""}],"html":"<p>חתיכת בצק a roll of dough  ירוש׳ חל׳ ג׳ נ״ט ע״א: חלה כמין גבלול.</p>","notation":["ז׳"]},"35061":{"h":"גִּבְלִית","r":"KRU03575","alt":[],"source":"krupnik","glosses":[{"text":"a Giblean) balcony","label":""}],"html":"<p>מין גזוזטרא (a Giblean) balcony  תוס׳ צוקרמ׳ אהל׳ י״ד: איזו היא גבלית כל שמניקה מכאן ומכאן ומשייר מן האמצע.</p>","notation":["נ׳"]},"35062":{"h":"גַּבְלָן","r":"KRU03576","alt":[],"source":"krupnik","glosses":[{"text":"Highland, District of Gablan","label":""}],"html":"<p>שם ארץ מישור בראשי ההרים Highland, District of Gablan  סוטה מ״ט ע״ב: הגליל יחרב והגבלן ישום ועי׳ גַּבְלָא.</p>","notation":[]},"35063":{"h":"גָּבַן","r":"KRU03577","alt":[],"source":"krupnik","glosses":[{"text":"to form cheese","label":"גִּבֵּן פיעל"}],"html":"<p>גִּבֵּן פיעל עשה גבינה to form cheese  שבת ל״ה ע״א: מגבן חייב משום בונה.\nהִגְבִּין הפע׳, כנ״ל. תוס׳ שבת י׳ י״ג: החולב והמחבץ והמגבין בגרוגרת. </p>","notation":["Source marks no qal form"]},"35064":{"h":"גִּבְנָא","r":"KRU03578","alt":[],"source":"krupnik","glosses":[{"text":"hump, height","label":""}],"html":"<p>חטוטרת, מקום גבוה hump, height  ספרי דבר׳ הוצ׳ א״ש נ״א: גבניא דאשקלון. ועי׳ גִּיבְנָא.</p>","notation":["ז׳"]},"35065":{"h":"גַּבְנוּן","r":"KRU03579","alt":[],"source":"krupnik","glosses":[{"text":"humpbacked","label":""}],"html":"<p>בעל חטוטרות humpbacked  מכי׳ יתר׳ בחודש ד׳: כלכם גבנונים אתם.</p>","notation":["ת׳"]},"35066":{"h":"גְּבַע","r":"KRU03582","alt":["אַגְּבַּע"],"source":"krupnik","glosses":[{"text":"to waddle","label":""}],"html":"<p>אפ׳, צבה to waddle  ירוש׳ דמאי א׳ כ״ב ע״א: מגבע ואתי.</p>","notation":[]},"35067":{"h":"גִּבְעוֹל","r":"KRU03583","alt":[],"source":"krupnik","glosses":[{"text":"calyx or capsule of plants","label":""}],"html":"<p>(קנה הצמח?) כוס הפרח calyx or capsule of plants  יומ׳ י״ד ע״א: ראשי הגבעולין; פד׳ פי״א מ״ז: גבעולין שלא גמלו; יומ׳ ע״ה ע״א: זרע פשתן בגבעולין.</p>","notation":["ז׳","Marked biblical in source"]},"35068":{"h":"גִּבְעֲתָא","r":"KRU03584","alt":[],"source":"krupnik","glosses":[{"text":"hill","label":""}],"html":"<p>גבעה hill  תרג׳ שופטי׳ ז׳ א׳ (מגבעת המורה): גבעתא.</p>","notation":["נ׳"]},"35069":{"h":"גָּבַר","r":"KRU03585","alt":[],"source":"krupnik","glosses":[{"text":"to be mighty","label":"גְּבָּר, מְגֻּבָּר פֻעל"}],"html":"<p>גְּבָּר, מְגֻּבָּר פֻעל היה אדיר to be mighty  תנחו׳ בובר חקת מ״ח: וריוח שהיה בין הדגלים מלא מים מגוברין וכו׳.</p>","notation":["Marked biblical in source"]},"35070":{"h":"גְּבַר","r":"KRU03586","alt":[],"source":"krupnik","glosses":[{"text":"to be strong, to prevail","label":""}],"html":"<p>היה חזק, הלך וגדול to be strong, to prevail  פסחי׳ ע״ו ע״א: עילאה גבר; שם: תתאה גבר; תרג׳ תהלי׳ ק״ג י״א: גבר טוביה.</p>","notation":["פ״ע"]},"35071":{"h":"גַּבֵּר","r":"KRU03587","alt":[],"source":"krupnik","glosses":[{"text":"to strengthen","label":"פיעל,"},{"text":"to cause to overpower","label":"אַגְּבַּר אפ׳"}],"html":"<p>פיעל, חיזק to strengthen  תרג׳ עמוס ה׳ ט׳ (המבליג שוד על עז): דמגבר חלשין.\nאַגְּבַּר אפ׳ עשה שיתגבר to cause to overpower  סנה׳ ל״ח ע״א: אגברו חמרא וכו׳.</p>","notation":[]},"35072":{"h":"גֶּבֶר","r":"KRU03588","alt":[],"source":"krupnik","glosses":[{"text":"cock","label":"1"},{"text":"membrum virile","label":"2"}],"html":"<p>1 תרנגול cock  יומא פ״א מ״ח: ולא היתה קריאת הגבר מגעת עד שהיתה עזרה מלאה מישראל.\n2 אבר הזכרות membrum virile  בכור׳ פ״ז מ״ה: המאושכן ובעל גבר.</p>","notation":["Marked biblical in source"]},"35073":{"h":"גְּבַר²","r":"KRU03589","alt":["גַּבְרָא"],"source":"krupnik","glosses":[{"text":"man","label":""},{"text":"a certain man, euphem: I, thou","label":""}],"html":"<p>איש man  בר׳ ס״ג ע״א: באתר דלית גבר תמן הוי גבר; ב״מ צ״ז ע״א: גברא דנשי קטלוה לא דינא ולא דיינא. הַהוּא גַּבְרָא, איש אחד, בהשאלה: אני, אתה a certain man, euphem: I, thou  ב״מ צ״ז ע״א: ההוא גברא דשאיל שונרא מחבירו וכו׳; גיט׳ נ״ה ע״ב: מכדי ההוא גברא בעל דבבא דההוא גברא הוא. </p>","notation":[]},"35074":{"h":"גִּבָּרָא","r":"KRU03590","alt":[],"source":"krupnik","glosses":[{"text":"hero","label":""}],"html":"<p>גבור hero  תרג׳ בראש׳ ל״ו כ״ד: דאשכח ית גבריא במדברא.</p>","notation":["ז׳"]},"35075":{"h":"גִּבָּרוּתָא","r":"KRU03591","alt":[],"source":"krupnik","glosses":[{"text":"might, strength","label":"1"},{"text":"hero","label":"2"}],"html":"<p>1 גבורה might, strength  תרג׳ דברי׳ ג׳ כ״ד: (וכגבורותיך): גבורתיך.\n2 בעל גבורה, גבור hero  תרג׳ דברי׳ ל״ג כ״ט: נצחן גברותך.</p>","notation":["נ׳"]},"35076":{"h":"גַּבְרִית","r":"KRU03592","alt":[],"source":"krupnik","glosses":[{"text":"cock-like","label":""}],"html":"<p>כתרנגול cock-like  שבת ס״ו ע״ב: ותרנגולת שקרתה גברית.</p>","notation":["ת׳"]},"35077":{"h":"גְּבַרְתָּן","r":"KRU03594","alt":[],"source":"krupnik","glosses":[{"text":"brave, hero","label":""}],"html":"<p>חזק מאד, רב כח brave, hero  ספרי דברי׳ ש״ה: גברתן שכמותך; במ״ר ז׳: מכה גברתנית.</p>","notation":["ת׳"]},"35078":{"h":"גְּבַרְתָּנִית","r":"KRU03595","alt":[],"source":"krupnik","glosses":[{"text":"powerful, overwhelming","label":""}],"html":"<p>חזקה מאד powerful, overwhelming  ויק״ר י״ח: מכה גברתנית ומתשת.</p>","notation":["ת׳"]},"35079":{"h":"גָּבַשׁ","r":"KRU03596","alt":["גִּבֵּשׁ"],"source":"krupnik","glosses":[{"text":"to fill with piles of stones","label":"פיעל,"}],"html":"<p>פיעל, מלא בצרורות to fill with piles of stones  תוס׳ אהל׳ י״ז: שגבשו בגבושין.</p>","notation":[]},"35080":{"h":"גְּבַשׁ","r":"KRU03597","alt":[],"source":"krupnik","glosses":[{"text":"to heap up","label":""}],"html":"<p>צבר to heap up  תרג׳ משלי ו׳ ח׳ (אגרה בקציר): וגבשא בחצדא מיכלה.</p>","notation":["פ״י"]},"35081":{"h":"גַּבְשׁוּשִׁית","r":"KRU03599","alt":["גַּבְשׁוּשׁיתָא"],"source":"krupnik","glosses":[{"text":"heap, pile, mound","label":""}],"html":"<p>בליטה, גל heap, pile, mound  שבת ע״ג ע״ב: היתה לו גבשושית ונטלה; תרג׳ שה״ש ד׳ א׳: ועבדו גבשושיתא (בערוך כן, בהוצ׳: גלשושיתא).</p>","notation":[]},"35082":{"h":"גַּבַּת","r":"KRU03600","alt":[],"source":"krupnik","glosses":[{"text":"name of a town, Gabbath","label":""}],"html":"<p>שם עיר name of a town, Gabbath  רות״ר ל״ה ע״ב: מגבת ועד אנטיפרס.</p>","notation":[]},"35083":{"h":"גָּג","r":"KRU03601","alt":[],"source":"krupnik","glosses":[{"text":"upper portion, top","label":""}],"html":"<p>הקצה העליון של פרי וכדומה, הקו העליון של האותיות upper portion, top  חול׳ ס״ז ע״ב: גג תמרה: ירוש׳ יבמ׳ ח׳ ט׳ ע״א: רוב גגה של עטרה; שבת ק״ד ע״ב: כגון שנטלו לגגו של חית ועשאו שני זיינין.</p>","notation":["Marked biblical in source"]},"35084":{"h":"גַּגּוֹת צְרִיפִין","r":"KRU03602","alt":[],"source":"krupnik","glosses":[{"text":"name of a town","label":""}],"html":"<p>שם עיר name of a town  מנח׳ ס״ד ע״ב: גגות צריפין.</p>","notation":[]},"35085":{"h":"גַּד","r":"KRU03603","alt":[],"source":"krupnik","glosses":[{"text":"wand","label":""}],"html":"<p>מקל wand  תרג׳ יב״ע במדב׳ כ״ב ז׳: גדין דקסמין חתימין (כן בערוך, בכ״י: ומוגדין).</p>","notation":["ז׳"]},"35086":{"h":"גַּד²","r":"KRU03604","alt":[],"source":"krupnik","glosses":[{"text":"bitter, acrid","label":""}],"html":"<p>מר וחריף bitter, acrid  שמו״ר ז׳: הגוים טועמין אותו מר וגד.</p>","notation":["ת׳"]},"35087":{"h":"גֵּד","r":"KRU03605","alt":[],"source":"krupnik","glosses":[{"text":"wormwood","label":""}],"html":"<p>מין לענה wormwood  תנחו׳ בובר בשלח כ׳: וכיון שהיה (המן) יורד היו אומות העולם באין לשתות ממנו והוא נעשה בפיהם גד ולענה; ועי׳ גַּד הנ״ל.</p>","notation":["ז׳"]},"35088":{"h":"גַּד³","r":"KRU03606","alt":[],"source":"krupnik","glosses":[{"text":"Gad Javan (Greek Fortune) a town near Jerusalem","label":""}],"html":"<p>גַּד יָוָן שם עיר Gad Javan (Greek Fortune) a town near Jerusalem  זבחי׳ פ״א מ״ה: כמן גד יון לשילוח.</p>","notation":["Marked biblical in source"]},"35089":{"h":"גַּדָּא","r":"KRU03607","alt":[],"source":"krupnik","glosses":[{"text":"luck, genius, godhead","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 מזל, אושר, ברכה, אליל האושר אצל העמים הקדמונים luck, genius, godhead  ב״ר ע״א: גדא דביתא; שם ס״ה: גדא דע״ז דאת קאים (ביה); קוה״ר ז׳ כ״ו (ומוצא אני): מה ביש גדא דההיא איתתא; חול׳ מ׳ ע״א: גדא דהר.\n2 שם איש a man’s name  עירובי׳ י״א ע״ב: רב גדא.</p>","notation":["ז׳"]},"35090":{"h":"גַּדַּאי","r":"KRU03608","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  כתוב׳ ק״ה ע״א: אדמון בן גדאי. </p>","notation":["שם איש"]},"35091":{"h":"גדבל","r":"KRU03609","alt":[],"source":"krupnik","glosses":[{"text":"to knead","label":""}],"html":"<p>גילגל to knead  גיט׳ ס״ט ע״א: וניגדבל (צ״ל וניגרבל) בקוטמא; ועי׳ גָּבַל.</p>","notation":["פ״י","Source emendation: גַּרְבֵּל"]},"35092":{"h":"גְּדָבְרָא","r":"KRU03610","alt":[],"source":"krupnik","glosses":[{"text":"collector","label":""}],"html":"<p>גזבר collector  דניא׳ ג׳ ב׳: גדבריא; תרג׳ קהל׳ ב׳ ז׳: גדברין די ממנן על מזונא.</p>","notation":["ז׳"]},"35093":{"h":"גַּדְגַּדְנִית","r":"KRU03611","alt":[],"source":"krupnik","glosses":[{"text":"melilot, a kind of clover","label":""}],"html":"<p>מין ירק והוא מאכל לבהמה melilot, a kind of clover  ברכות נ״ז ע״ב: שלשה נכנסין לגוף ואין הגוף נהנה מהן גדגדניות וכפניות ופגי תמרה ועי׳ הִנְדְּקוֹקָא.</p>","notation":["נ׳"]},"35094":{"h":"גָּדַד","r":"KRU03613","alt":[],"source":"krupnik","glosses":[{"text":"to cut, to cut off","label":""},{"text":"stripped (of branches), trnsf: empty-handed","label":""},{"text":"to fix the price","label":""},{"text":"to be cut off","label":""},{"text":"to cut off, to level","label":""}],"html":"<p>1) חתך, קטע to cut, to cut off  פרה פ״ב מ״ב: פרה שקרניה וטלפיה שחורים יגוד; כלי׳ פי״ח מ״ה: גדד שתי לשונות לוכסן גדד שתי כרעים לוכסן. גָּדוּד פעו׳ 1) מקוטע ובהשאלה: בידים ריקניות stripped (of branches), trnsf: empty-handed  כתוב׳ נ״א ע״א: סוף סוף כל העומד ליגדד כגדוד דמי; ב״ר ס״ח: לא נזם אחד ולא צמוד אחד ר׳ חנינה אמר גדוד שלחו (יצחק את יעקב). 2) קצב את המחיר to fix the price  ב״ב י״ג ע״א: גוד או אגוד. נִּגְדַּד נפע׳ נחתך, נקצץ to be cut off  כתוב׳ נ״א ע״א: כל העומד ליגדד כגדוד דמי. גִּדֵּד פיע׳, חתך, כרת ובהשאלה: החריב והשמיד to cut off, to level  תנחו׳ כי תשא י״ג: וגדד משכנותיהם ומשתותיהם של אוה״ע. </p>","notation":["Marked biblical in source"]},"35095":{"h":"גֹּדֵּד","r":"KRU03614","alt":[],"source":"krupnik","glosses":[{"text":"to make incisions in one’s body","label":""}],"html":"<p>פועל, עשה שרטת בעור הבשר to make incisions in one’s body  יבמו׳ י״ג ע״ב: א״כ לימא קרא לא תגודדו (במקום לא תתגודדו).</p>","notation":[]},"35096":{"h":"גְּדַד","r":"KRU03615","alt":[],"source":"krupnik","glosses":[{"text":"to chastise","label":"2"},{"text":"to grow (the luck)","label":"3"}],"html":"<p>1 עי׳ גּדָדַ 1. דניאל ד׳ י״א: וכן אמר גדו אילנא; ביצה ו׳ ע״א: אפי׳ למיגז (בכ״י מינכן ובערוך: למיגד) ליה גלימא. \n2 החרים, ענש to chastise  נדרי׳ ל״ו ע״ב: צנעיה ואי לא ציית גדייה.\n3 התמזל (רש״י) to grow (the luck)  שבת׳ ס״ז ע״ב: גד גדי וסינוק לא.</p>","notation":["פ״י"]},"35097":{"h":"גְּדוּד","r":"KRU03617","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום –· name of a place  ערבי׳ פ״ט מ״ו: וגדוד וחדיד ואונו וירושלם.</p>","notation":[]},"35098":{"h":"גְּדוּדָא","r":"KRU03618","alt":["גִּדּוּדָא"],"source":"krupnik","glosses":[{"text":"a tree stripped of all branches","label":""}],"html":"<p>עץ שנשרו ענפיו כולם a tree stripped of all branches  עירוב׳ ק׳ ע״ב: והא קא נתרו קינסי–בגדודא.</p>","notation":[]},"35099":{"h":"גְּדוּדִי","r":"KRU03619","alt":[],"source":"krupnik","glosses":[{"text":"empty handed","label":""}],"html":"<p>בידים ריקניות empty handed  ילקו׳ בראשי׳ קי״ז: גדודי שלחו. ועי׳ גָּדַד.</p>","notation":["ת׳"]},"35100":{"h":"גְּדוּדֵי","r":"KRU03620","alt":[],"source":"krupnik","glosses":[{"text":"haughty","label":""}],"html":"<p>גאותן haughty  תרג׳ תהלי׳ ל״א כ״א (תסתירם בסתר פניך מרכסי איש): מגברי גדודי.</p>","notation":["ת׳"]},"35101":{"h":"גְּדוּדִית","r":"KRU03621","alt":[],"source":"krupnik","glosses":[{"text":"small troop","label":"1"},{"text":"ruins","label":"2"}],"html":"<p>1 גדוד קטן small troop  ספרא בחוק׳ (והשמותי את מקדשיכם): מן הגדודית.\n2 הרבה ruins  עירוב׳ פ״ה מ״א: היו שם גדודיות גבוהות עשרה טפחים.</p>","notation":["נ׳"]},"35102":{"h":"גְּדוּדְקִי","r":"KRU03622","alt":[],"source":"krupnik","glosses":[{"text":"cage","label":""}],"html":"<p>כלוב cage  שבת ק״ו ע״ב: אינו חייב עד שיכניסנו לגורזקי (בערוך: לגדודקי) שלו.</p>","notation":["נ׳"]},"35103":{"h":"גְּדוּדְתָה","r":"KRU03623","alt":[],"source":"krupnik","glosses":[{"text":"hord","label":""}],"html":"<p>גדוד hord  ירוש׳ דמ׳ א׳ כ״א ב׳: במקום שהיתה גררתה (בר״ש: גדודתה).</p>","notation":["נ׳"]},"35104":{"h":"גָּדוֹל","r":"KRU03624","alt":[],"source":"krupnik","glosses":[{"text":"great, distinguished","label":""}],"html":"<p>. – ת׳, חשוב great, distinguished  שבת ס״ג ע״א: גדול המלוה יותר מן העושה צדקה; ב״ב ט׳ ע״א: גדול המעשה יותר מן העושה; ברכ׳ ל״ג ע״א: גדולה דעה שנתנה בתחלת ברכה של חול.</p>","notation":[]},"35105":{"h":"גְּדוֹל הָעוֹלָמִים","r":"KRU03625","alt":[],"source":"krupnik","glosses":[{"text":"The Lord","label":""}],"html":"<p>האלהים The Lord  ב״ר ק׳: גדול העולמים.</p>","notation":[]},"35106":{"h":"גְּדוֹלֵי רוֹמִי","r":"KRU03626","alt":[],"source":"krupnik","glosses":[{"text":"Roman dignitaries","label":""}],"html":"<p>אצילי רומי Roman dignitaries  גיט׳ נ״ו ע״א: גדולי רומי.</p>","notation":[]},"35107":{"h":"גְּדוֹלִים","r":"KRU03627","alt":[],"source":"krupnik","glosses":[{"text":"the larger functions of the body","label":""}],"html":"<p>נקבים גדולים, צרכי הרקת הגוף the larger functions of the body  ברכ׳ כ״ג ע״ב: כאן לגדולים כאן לקטנים.</p>","notation":[]},"35108":{"h":"גִּדּוּל","r":"KRU03628","alt":[],"source":"krupnik","glosses":[{"text":"growth","label":"1"},{"text":"anything that grows","label":"2"}],"html":"<p>1 צמיחה growth  ברכ׳ פ״ו מ״ג: על דבר שאין גדולו מן הארץ אומר שהכל.\n2 הדבר הגדל, צמח anything that grows  ברכ׳ מ׳ ע״ב: למימרא דכמהין ופטריות לאו גדולי קרקע נינהו. ועי׳ גִּידּוּל.</p>","notation":["ז׳"]},"35109":{"h":"גִּדּוּף","r":"KRU03629","alt":[],"source":"krupnik","glosses":[{"text":"blasphemy","label":""}],"html":"<p>ר׳ גִּידּוּפִין, חלול השם blasphemy  ירוש׳ תרו׳ א׳ מ׳ ע״ד: תפלתו גדופין.</p>","notation":["Marked biblical in source"]},"35110":{"h":"גַּדּוּפִי","r":"KRU03630","alt":[],"source":"krupnik","glosses":[{"text":"blasphemer","label":""}],"html":"<p>מגדף blasphemer  שבת ע״ה ע״א: מגושתא רב ושמואל חד אמר חרשי וחד אמר גדופי.</p>","notation":["ז׳"]},"35111":{"h":"גִּדּוּר","r":"KRU03631","alt":[],"source":"krupnik","glosses":[{"text":"fencing in, self-restraint","label":""}],"html":"<p>עשית גדר וסייג, פרישה fencing in, self-restraint  ל״ב: אמר חב״א כדאי היה גדור ערוה בעצמו שנגאלו ישראל על ידו.</p>","notation":["ז׳"]},"35112":{"h":"גְּדוֹר","r":"KRU03632","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ ר״ה ב׳ נ״ח ע״א: מכוור וגדור.</p>","notation":[]},"35113":{"h":"גְּדוּרָה","r":"KRU03633","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ מעש׳ א׳ מ״ח ע״ג: חרובי גדורה.</p>","notation":[]},"35114":{"h":"גָּדוּשׁ","r":"KRU03634","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>שם איש a man’s name  תוס׳ מעש״ש א׳ י״ד: גדוש.</p>","notation":[]},"35115":{"h":"גְּדֵּי","r":"KRU03635","alt":[],"source":"krupnik","glosses":[{"text":"to cut off, to excommunicate","label":"גַּדֵּי פַעל,"}],"html":"<p>גַּדֵּי פַעל, כרת, החרים to cut off, to excommunicate  נדה ל״ו ע״ב: ואי לא צאית גדייה הוא סבר גדייה א״ל.</p>","notation":[]},"35116":{"h":"גְּדִי","r":"KRU03636","alt":[],"source":"krupnik","glosses":[{"text":"the Capricorn, a sign in the Zodiac","label":"1"},{"text":"the tender grain in its husks","label":"2"}],"html":"<p>1 אחד מי״ב המזלות שבשמים the Capricorn, a sign in the Zodiac  פסיק״ר כ׳: ואחריו מה אתה בורא גדי; ילק׳ במדבר תשפ״ה: הרי נכנס הזאב לגדי.\n2 תבואה שלא בשלה the tender grain in its husks  פסיק׳ עשר צ״ט ע״ב: אל תגרמו לי לבשל גדיים עד שהן במעי אמותיהן.</p>","notation":[]},"35117":{"h":"גַּדְיָא","r":"KRU03637","alt":[],"source":"krupnik","glosses":[{"text":"a young animal, kid","label":"1"},{"text":"a man’s name","label":"2"},{"text":"name of a place","label":"3"}],"html":"<p>1 גדי a young animal, kid  תרג׳ ברא׳ ל״ח י״ז (גדי עזים): גדיא בר עיזי.\n2 שם איש a man’s name  פסיק׳ זכור כ״ה ע״א־ע״ב: יודן בן גדיא.\n3 שם מקום name of a place  ירוש׳ סוט׳ ט׳ כ״ד ע״ב: אצל בית גדיא.</p>","notation":["ז׳"]},"35118":{"h":"גַּדַּיָא","r":"KRU03638","alt":[],"source":"krupnik","glosses":[{"text":"luck, genius","label":""}],"html":"<p>מזל, אלילי האושר luck, genius  ירוש׳ ע״ז ג׳ מ״ג ע״א: גדיא קורין אותו גליא; ועי׳ גַּדָּא.</p>","notation":["ז״ר"]},"35119":{"h":"גדיאן","r":"KRU03639","alt":[],"source":"krupnik","glosses":[{"text":"a kind of locust","label":""}],"html":"<p>מין ארבה a kind of locust  חול׳ ס״ה ע״א: חגב זה גדיאן.</p>","notation":["ז׳","Source emendation: נַדְיָאן"]},"35120":{"h":"גְּדִידָה","r":"KRU03641","alt":[],"source":"krupnik","glosses":[{"text":"incision in the flesh","label":"1"},{"text":"cutting dates","label":"2"}],"html":"<p>1 חתך בבשר incision in the flesh  מכו׳ כ״א ע״ב: ששריטה ביד וגדידה בכלי.\n2 לקיטת התמרים cutting dates  ב״ב ל״ו ע״ב: חכמים אומרים עד שיגדוד שלשה גדידות.</p>","notation":["נ׳"]},"35121":{"h":"גְּדִידִים","r":"KRU03642","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  קדוש׳ ס״ו ע״א: היה שם זקן אחד ויהודה בן גדידים (גדיה) שמו. </p>","notation":["שם איש"]},"35122":{"h":"גַּדְיָיתָא","r":"KRU03644","alt":[],"source":"krupnik","glosses":[{"text":"young animal, kid","label":""}],"html":"<p>גדיה young animal, kid  תרג׳ יב״ע במדב׳ ט״ו כ״ז (עז): גדייתא.</p>","notation":["נ׳"]},"35123":{"h":"גָּדֵיל","r":"KRU03645","alt":[],"source":"krupnik","glosses":[{"text":"one entering on puberty","label":""}],"html":"<p>נער one entering on puberty  תוס׳ מקוא׳ ו׳ י׳: כשות של גדיל וכו׳.</p>","notation":["ז׳"]},"35124":{"h":"גָּדִיל","r":"KRU03646","alt":[],"source":"krupnik","glosses":[{"text":"twist table-cloth","label":""}],"html":"<p>מפה וכדומה שמכסין בה את השלחן, twist table-cloth  ב״ב נ״ז ע״ב: שני שלישי גדיל ושליש גילוי.</p>","notation":["Marked biblical in source"]},"35125":{"h":"גְּדִיל","r":"KRU03647","alt":[],"source":"krupnik","glosses":[{"text":"heaped (measure)","label":""}],"html":"<p>גדוש heaped (measure)  ירוש׳ פסח׳ ד׳ ל״א ע״ג: גדיל או מחוק.</p>","notation":["ת׳"]},"35126":{"h":"גְּדִילָא","r":"KRU03648","alt":[],"source":"krupnik","glosses":[{"text":"twisted threads, fringes","label":""}],"html":"<p>ציצית twisted threads, fringes  מנח׳ ל״ט ע״ב: וגדילא מיגדיל.</p>","notation":["ז׳"]},"35127":{"h":"גְּדִילָה","r":"KRU03649","alt":[],"source":"krupnik","glosses":[{"text":"growth, natural position","label":"1"}],"html":"<p>1 גידול growth, natural position  נדה ס״ז ע״א: האשה לא תטבול אלא דרך גדילתה.\n2 עי גְּדִילָא. ספרי במדב׳ קט״ו: שתהא גדילה יוצא וכו׳. </p>","notation":["נ׳"]},"35128":{"h":"גְּדִילוּ","r":"KRU03650","alt":[],"source":"krupnik","glosses":[{"text":"wreathing","label":""}],"html":"<p>שזירה wreathing  תרג׳ שמות כ״ח י״ד (מעשה עבות): גדילו.</p>","notation":["נ׳"]},"35129":{"h":"גְּדִילְתָּא","r":"KRU03651","alt":[],"source":"krupnik","glosses":[{"text":"rope, chain, fringe, plat of hair","label":""}],"html":"<p>דבר שזור וקלוע, מעשה עבות rope, chain, fringe, plat of hair  תרג׳ ישעי׳ ה׳ י״ח (וכעבות העגלה): גדילת עגלתא; תרג׳ שופט׳ ט״ו י״ג (עבותים חדשים): גדילן חדתין.</p>","notation":["נ׳"]},"35130":{"h":"גָּדֵיר","r":"KRU03653","alt":[],"source":"krupnik","glosses":[{"text":"fence, precaution against trespassing the law","label":""}],"html":"<p>גדר, סיָג fence, precaution against trespassing the law  ירוש׳ ע״ז ב׳ מ״א ע״א: ולא פרצת גדירן של חכמים.</p>","notation":["ז׳"]},"35131":{"h":"גְּדֵירָא","r":"KRU03654","alt":["גָּדֵירָא"],"source":"krupnik","glosses":[{"text":"fence","label":""}],"html":"<p>גדר fence  תרג׳ יב״ע ויקר׳ ח׳ כ״ג (תנוך אזן): גדירא מיצעא דאודן; ב״ק כ״ג ע״ב: ליגדור מר גדירא בארעיה.</p>","notation":[]},"35132":{"h":"גְּדֵירָה","r":"KRU03655","alt":[],"source":"krupnik","glosses":[{"text":"fence, fortification, self-restraint","label":""}],"html":"<p>גדר, מבצר, פרישה fence, fortification, self-restraint  פסיק״ר כ״ו: עשוי לו גדירה גדירה של אבנים; שהש״ר כ״ד: גדירת ערוה.</p>","notation":["נ׳"]},"35133":{"h":"גְּדִישׁ","r":"KRU03656","alt":[],"source":"krupnik","glosses":[{"text":"heaped (measure)","label":""}],"html":"<p>מלא וגדוש heaped (measure)  אסת״ר א׳ ד׳ (בהראותו): אמר לון היכן יהבתיה לכון גדיש או מחיק.</p>","notation":["ת׳"]},"35134":{"h":"גַּדֵּישׁ","r":"KRU03657","alt":[],"source":"krupnik","glosses":[{"text":"leader of a blind man","label":""}],"html":"<p>מנהיג את העוֵר leader of a blind man  ילק׳ קהל׳ תתקע״ב: והוה ההוא וכו׳ גדיש ליה וכו׳.</p>","notation":["ז׳"]},"35135":{"h":"גְּדִישָׁא","r":"KRU03658","alt":[],"source":"krupnik","glosses":[{"text":"pile, mound","label":""}],"html":"<p>גדיש, ערֵמה pile, mound  תרג׳ איוב ה׳ כ״ו (כעלות גדיש): היך מיסק גדישא.</p>","notation":["ז׳"]},"35136":{"h":"גְּדִישׁוּתָא","r":"KRU03659","alt":[],"source":"krupnik","glosses":[{"text":"heaped measure","label":""}],"html":"<p>גודש heaped measure  תרג׳ יב״ע ויקר׳ י״ט ל״ה: בגדישותא ובמחקא.</p>","notation":["נ׳"]},"35137":{"h":"גָּדַל","r":"KRU03660","alt":[],"source":"krupnik","glosses":[{"text":"to become of age","label":"הִגְדִּיל הפע׳,"},{"text":"to be nursed","label":"הִתְגַּדֵּל התפ׳,"}],"html":"<p>הִגְדִּיל הפע׳, בא בשנים to become of age  יבמ׳ פ״י מ״ט: ומשהגדיל נשא אשה אחרת.\nהִתְגַּדֵּל התפ׳, נתחנך to be nursed  תוס׳ כתוב׳ י״א ד׳: בן שמת אביו ואמו אומרת התגדל אצלי וכו׳.</p>","notation":["Marked biblical in source"]},"35138":{"h":"גָּדַל²","r":"KRU03661","alt":[],"source":"krupnik","glosses":[{"text":"to plait, to dress the hair","label":""}],"html":"<p>קלע וסבך חוטים או שערות וכדומה to plait, to dress the hair  כלי׳ ט״ז ז׳: והאמום של גודלי מצנפת; שבת צ״ד ע״ב: הגודלת משום אורגת: ביצה ל״ב ע״ב: אין גודלין אותה (את הפתילה) לכתחלה ביו״ט.</p>","notation":["פ״י"]},"35139":{"h":"גְּדַל","r":"KRU03662","alt":[],"source":"krupnik","glosses":[{"text":"to grow, to be tall","label":"1"}],"html":"<p>1 בא בשנים, נהיה גדול to grow, to be tall  קידו׳ ע״א ע״ב: גדל ולא נסיב וכו׳.</p>","notation":["פ״ע"]},"35140":{"h":"גַּדֵּל","r":"KRU03663","alt":[],"source":"krupnik","glosses":[{"text":"to raise, to rear","label":"פַעל,"},{"text":"to be exalted","label":"אִתְגַּדַּל אתפ׳,"}],"html":"<p>פַעל, גידל, חינך to raise, to rear  חגיג׳ ד׳ ע״ב: מרים מגדלא דרדקי.\nאִתְגַּדַּל אתפ׳, נתגדל to be exalted  תרג׳ תהל׳ קי״ד א׳ (גדלת מאד): אתגדלתא.</p>","notation":[]},"35141":{"h":"גְּדַל²","r":"KRU03664","alt":[],"source":"krupnik","glosses":[{"text":"to plait, to dress the hair","label":""}],"html":"<p>עשה מעשה גדיל, קלע to plait, to dress the hair  גיט׳ ס״ט ע״א: ניגדול תרתי וכו׳.</p>","notation":["פ״י"]},"35142":{"h":"גִּדָּל","r":"KRU03666","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  יומא ס״ט ע״ב: רב גדל אמר וכו׳.</p>","notation":[]},"35143":{"h":"גִּדָּלוֹן","r":"KRU03667","alt":[],"source":"krupnik","glosses":[{"text":"elevation to dignity","label":""}],"html":"<p>התעלות elevation to dignity  ילק׳ תהל׳ תשע״ז: גדלון אחר גדלון.</p>","notation":["ז׳"]},"35144":{"h":"גַּדְּלַיי","r":"KRU03668","alt":[],"source":"krupnik","glosses":[{"text":"weaver","label":""}],"html":"<p>אורג weaver  ירוש׳ כתוב׳ י&quot;ב ל״ה ע״א: חד גדליי אתא לקמיה דר׳ יוחנן.</p>","notation":["ז׳"]},"35145":{"h":"גַּדֶּלֶת","r":"KRU03669","alt":[],"source":"krupnik","glosses":[{"text":"hair-dresser","label":""}],"html":"<p>מי שאומנתה לגדל שערות hair-dresser  ויק״ר י&quot;ט: הלכו ופייסו לגדלת וגדלת למלכה.</p>","notation":["נ׳"]},"35146":{"h":"גָּדַם","r":"KRU03670","alt":[],"source":"krupnik","glosses":[{"text":"to lop off, to stump","label":""},{"text":"to be cut off","label":""}],"html":"<p>כרת הקצה מדבר, חתך to lop off, to stump  תוס׳ צוק׳ בכור׳ ה׳ ד׳: אצבעותיו גדומות. הִתְגַּדֵּם התפ׳, נקצץ to be cut off  תעני׳ כ״א ע״א: ידי שלא חסו על ידיך יתגדמו. </p>","notation":["פ״י"]},"35147":{"h":"גְּדָנְפָא","r":"KRU03672","alt":[],"source":"krupnik","glosses":[{"text":"rim, enclosure","label":""}],"html":"<p>זר, מסגרת rim, enclosure  סוכ׳ כ׳ ע״ב: אית ליה גדנפא וכו׳ לית ליה גדנפא.</p>","notation":["ז׳"]},"35148":{"h":"גְּדַע","r":"KRU03673","alt":[],"source":"krupnik","glosses":[{"text":"to cut, to chop, to lop off","label":""},{"text":"to be cut, to be mutilated","label":""}],"html":"<p>קצץ, כרת to cut, to chop, to lop off  תרג׳ ש״ב י׳ ד׳ (ויכרת): וגדע ית פלגות דקניהון. אִתְגַּדַּע אתפ׳ נכרת to be cut, to be mutilated  תרג׳ יב״ע שמות י״ב י״ב: טעוות אבנא מתגדעין. </p>","notation":["פ״י"]},"35149":{"h":"גָּדַף","r":"KRU03674","alt":[],"source":"krupnik","glosses":[{"text":"to cut, to scrape","label":""}],"html":"<p>חטט, קנח to cut, to scrape  פסח׳ מ״ב ע״א: מים הגרופים (בערוך: הגדופים) מן המולייר.</p>","notation":["פ״י","Marked biblical in source"]},"35150":{"h":"גַּדֵּיף","r":"KRU03676","alt":["גְּדַף"],"source":"krupnik","glosses":[{"text":"to blaspheme","label":"פַעל, 1"},{"text":"to sneer at","label":"פַעל, 2"}],"html":"<p>פַעל, 1 חרף, חילל את השם to blaspheme  תרג׳ שופט׳ ה׳ י״ח (חרף): דגדיפו קדם ה׳.\nפַעל, 2 לעג to sneer at  ע״ז ל״ה ע״א: מגדף בה ר׳ ירמיה.</p>","notation":[]},"35151":{"h":"גַּדְפָא","r":"KRU03677","alt":[],"source":"krupnik","glosses":[{"text":"wing","label":"1"},{"text":"feather, plumage, trnsf: bird","label":"2"},{"text":"rim, border","label":"3"}],"html":"<p>1 כנף wing  תרג׳ איוב ל״ט י״ג (כנף רננים): גדפא.\n2 נוצה, בהשאלה: עוף feather, plumage, trnsf: bird  כתוב׳ ק״ה ע״ב: פרח גדפא ארישיה; גיט׳ פ״ו ע״א: גדפא דאווזא.\n3 קצה, שפה לפי הכלי rim, border  תרג׳ איוב ל״ה י״ג (בכנפות הארץ): בגדפי ארעי. ועי׳ גְּדָנְפָא.</p>","notation":["ז׳"]},"35152":{"h":"גדפה","r":"KRU03678","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ ב״מ ד׳ ט׳ ע״ג: סלקון גבי ר׳ יוסי לגדפה.</p>","notation":[]},"35153":{"h":"גַּדְפִי","r":"KRU03679","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  סנה׳ ד׳ ע״ב: טט בגדפי שתים. ועי׳ כַּתְּפִי.</p>","notation":[]},"35154":{"h":"גַּדְּפָן","r":"KRU03680","alt":[],"source":"krupnik","glosses":[{"text":"blasphemer","label":""}],"html":"<p>מי שמגדף תמיד blasphemer  ירוש׳ מ״ק ג׳ פ״ג ע״ב: משרבו הגדפנין פסקו מלקרוע (על קללת השם).</p>","notation":["ז׳"]},"35155":{"h":"גָּדַר","r":"KRU03682","alt":[],"source":"krupnik","glosses":[{"text":"to cut, esp: to harvest dates","label":""},{"text":"to control, to ward off","label":""},{"text":"to be guarded","label":""}],"html":"<p>1) קצץ, ביחוד את התמרים מן העץ to cut, esp: to harvest dates  ב״ב ל״ו ע״ב: עד שיגדור שלשה גדירות: שבת נ׳ ע״א: חריות של דקל שגדרן לעצים. 2) עשה מחיצה בפני דבר, מנע, פרש to control, to ward off  ב״ר מ״ט: אתה גודר את האף והאף לא יגדרך; ירוש׳ ברכ׳ ג׳ ו׳ ע״ג: דבר שהוא גודר את ישראל מן העברה; ב״מ ל״א ע״א: ראה מים ששוטפין ובאין הרי זה גודר בפניהם. נִּגְּדַּר נפע׳, נשמר, to be guarded  ויק״ר ל״ב: שרה גדרה את עצמה מן הערוה ונגדרו כל הנשים בזכותה. </p>","notation":["Marked biblical in source"]},"35156":{"h":"גִּידֵּר","r":"KRU03683","alt":[],"source":"krupnik","glosses":[{"text":"to cut into","label":"פיעל,"},{"text":"to distinguish one’s self, to raise one’s self above others, to be presumptuous","label":"הִתְגַּדֵּר התפ׳,"}],"html":"<p>פיעל, חתך to cut into  במד״ר י״ח: וגידר את הפרוכת וכו׳.\nהִתְגַּדֵּר התפ׳, לקח גדולה לעצמו, התרומם, התגאה על to distinguish one’s self, to raise one’s self above others, to be presumptuous  ברכ׳ י״ז ע״א: כשם שהוא אינו מתגדר במלאכתי כך אני איני מתגדר במלאכתו; חול׳ ו׳ ע״ב: אלא מקום הניחו לו אבותיו להתגדר בו; נדר׳ פ״א ע״א: כדי שלא יתגדרו על הצבור.</p>","notation":[]},"35157":{"h":"גְּדַר","r":"KRU03684","alt":[],"source":"krupnik","glosses":[{"text":"to fence in","label":"1"},{"text":"to deduct","label":"2"}],"html":"<p>1 עשה היקף מסביב לדבר to fence in  יבמ׳ צ׳ ע״ב: מיגדר מילתא שאני.\n2 חיסר to deduct  אסת״ר א׳ ד׳ (בהראותו): גדראניה מן פורני.</p>","notation":["פ״י"]},"35158":{"h":"גֶּדֶר","r":"KRU03685","alt":[],"source":"krupnik","glosses":[{"text":"guard, chastity","label":"1"},{"text":"guard against tresspassing the law","label":"2"},{"text":"name of a place","label":"3"}],"html":"<p>1 פרישה guard, chastity  ויק״ר כ״ד: גדר ערוה.\n2 סיָג guard against tresspassing the law  תוס׳ שביעי׳ ג׳ י״ג: לא גזרו אלא גדר שיכול לעמוד.\n3 שם מקום name of a place  עירוב׳ ס״א ע״א: מיטטרגי להו בני גדר לבני חמתן.</p>","notation":["Marked biblical in source"]},"35159":{"h":"גדרפוס","r":"KRU03688","alt":[],"source":"krupnik","glosses":[{"text":"a form of melancholy","label":""}],"html":"<p>עי׳ גַּנְדְּרוֹפּוֹס , מין חולי, מרה שחורה a form of melancholy  חגיג׳ ג׳ ע״ב: אימר גנדרופוס (בכ״י מינכן: גדרפוס) אחדיה.</p>","notation":["ז׳"]},"35160":{"h":"גָּדֵשׁ","r":"KRU03689","alt":[],"source":"krupnik","glosses":[{"text":"name of place","label":""}],"html":"<p>שם מקום name of place  מדר׳ שמואל ל׳ (הגלעדה): גדש.</p>","notation":[]},"35161":{"h":"גָּדַשׁ","r":"KRU03690","alt":[],"source":"krupnik","glosses":[{"text":"to heap, to put up stacks of grain","label":"1"},{"text":"to give heaped measure","label":"2"}],"html":"<p>1 צבר to heap, to put up stacks of grain  מנח׳ ע״א ע״א: גודשין לפני העומר.\n2 מלא את המדה למעלה משפתה to give heaped measure  ב״ב פ״ה מי״א: מקום שנהגו וכו׳ למחוק לא יגדוש.</p>","notation":["פ״י"]},"35162":{"h":"גָּדוּשׁ²","r":"KRU03691","alt":[],"source":"krupnik","glosses":[{"text":"heaped","label":"פעול,"},{"text":"to be heaped up","label":"נִגְּדַּשׁ נפע׳,"}],"html":"<p>פעול, צָבור heaped  תמי׳ פ״ה מ״ד: והבזך היה בתוכו מלא וגדוש קטורת.\nנִגְּדַּשׁ נפע׳, נתמלא יתר על המדה to be heaped up  מנח׳ פ״ט מ״ה: כל המדות שהיו במקדש היו נגדשות.\nהִגְּדִּישׁ עי׳ גָּדַשׁ 1. ב״ק פ״ו מ״ג: המגדש בתוך שדה חבירו שלא ברשות. </p>","notation":[]},"35163":{"h":"גְּדַשׁ","r":"KRU03692","alt":["גֵּדֵּש"],"source":"krupnik","glosses":[{"text":"to lead a blind man","label":"פַעל,"}],"html":"<p>פַעל, נהג את העוֵר to lead a blind man  ויק״ר כ״ב: עובדא הוי בתרין גברין דהוי עיילין לטבריא חד סמי וחד פתיח והוה ההוא פתיחא גדיש ליה.</p>","notation":[]},"35164":{"h":"גָּהָה","r":"KRU03695","alt":[],"source":"krupnik","glosses":[{"text":"to bulge, to hang over","label":""}],"html":"<p>עמד נטוי to bulge, to hang over  מו״ק י״ג ע״א: כותל הגוהה לרשות הרבים סותר ובונה כדרכו מפני הסכנה.</p>","notation":["פ״ע"]},"35165":{"h":"גְּהַט","r":"KRU03696","alt":[],"source":"krupnik","glosses":[{"text":"to erase","label":""}],"html":"<p>גרד, מחק to erase  בר׳ נ״ו ע״א: ויו דפטר חמור גהיט מתפילך.</p>","notation":["פ״י"]},"35166":{"h":"גָּהַץ","r":"KRU03701","alt":[],"source":"krupnik","glosses":[{"text":"to be glad","label":""}],"html":"<p>שמח to be glad  ב״ר ל״ט וא״ת שלא גהץ אברהם ושמח על דבור המקום וכ׳.</p>","notation":["פ״ע"]},"35167":{"h":"גִּיהֵץ","r":"KRU03702","alt":[],"source":"krupnik","glosses":[{"text":"to polish (clothes), to iron","label":"פיעל, הִגְהִיץ, הפ׳,"},{"text":"to be polished","label":"הִתְגָּהֵץ התפ׳,"}],"html":"<p>פיעל, הִגְהִיץ, הפ׳, החליק to polish (clothes), to iron  פסיק׳ בשלח צ״ב ע״א: אין מגהיצין אותו אלא באור; ילק׳ תהל׳ תרצ״א: ענני כבוד היו מגהצין וכו׳.\nהִתְגָּהֵץ התפ׳, הוחלק to be polished  שהש״ר ד׳ י״א (נפת): צא ולמד מן אמיינטון הזה שאינו מתגהץ אלא באור.</p>","notation":[]},"35168":{"h":"גָּהַק","r":"KRU03703","alt":[],"source":"krupnik","glosses":[{"text":"to belch","label":"גִּיהֵק פיעל"}],"html":"<p>גִּיהֵק פיעל הוציא רוח בקול שאון מקיבתו to belch  ברכ׳ כ״ד ע״א: ראיתי את רבי שגיהק ופיהק ונתעטש.</p>","notation":[]},"35169":{"h":"גּוֹ","r":"KRU03705","alt":[],"source":"krupnik","glosses":[{"text":"belly, innermost","label":""},{"text":"there is something in it","label":""}],"html":"<p>. תוך, פנים הדבר belly, innermost  פסח׳ ק״י ע״ב: אתיתי לגו. דְּבָרִים בְּגוֹ יש דברים בענין הזה, ולא לחנם הוא there is something in it  קידוש׳ מ״ד ע״ב: אמר שמואל צריכה גט וצריכה מיאון אמר קרנא דברים בגו אם גט למה מיאון אם מיאון למה גט. </p>","notation":["ז׳"]},"35170":{"h":"גַּו","r":"KRU03706","alt":[],"source":"krupnik","glosses":[{"text":"among, amid","label":""},{"text":"because, in consequence of","label":""}],"html":"<p>1) כנ״ל בנסמך גּוֹ. תרג׳ יחזק׳ כ״ט י״ב: (ועריה בתוך ערים) וקירוה בגו קירון; תרג׳ משלי כ״ו כ״ד (ובקרבו ישית מרמה): ובגויה סאם רמיותא. 2) תה״פ בתוך, בפנים among, amid  חול׳ מ״א ע״א: אית ליה שותפות בגוה; פסחי׳ ק״ו ע״ב: לא אתיתי לגו; ירוש׳ כלא׳ ט׳ ל״ב ע״ב: גו בני. מִן גַּו מפני, מתוך because, in consequence of  ירוש׳ ברכ׳ א׳ ג׳ ע״ב: מן גו דאינון ציבחר. מִגּוֹ עי׳ מִיגּוֹ. ב״מ ט׳ ע״ב: מגו דאי בעי מפקיר נכסי. </p>","notation":["Marked biblical in source"]},"35171":{"h":"גֵּו","r":"KRU03707","alt":[],"source":"krupnik","glosses":[{"text":"crowd","label":""}],"html":"<p>חבורה של בני אדם crowd  סנה׳ ע״ט ע״א: וארב לו וקם עליו וכו׳ פרט לזורק אבן לגו.</p>","notation":["Marked biblical in source"]},"35172":{"h":"גַּוָּא²","r":"KRU03709","alt":[],"source":"krupnik","glosses":[{"text":"belly, body","label":""}],"html":"<p>תוך, קרב belly, body  תרג׳ ויק׳ א׳ י״ג (והקרב): וגוא.</p>","notation":["ז׳"]},"35173":{"h":"גַּוָּאָה","r":"KRU03710","alt":[],"source":"krupnik","glosses":[{"text":"inner, inside","label":""}],"html":"<p>ותה״פ, פנימי, בתוך, בפנים inner, inside  זבחי׳ ט״ו ע״א: לא קשיא הא בבתי גואי הא בבתי בראי; תרג׳ מ״א ו׳ כ״ז (בתוך הבית): בגו ביתא גואה; חול׳ מ״ז ע״א: והני מילי מגוואי אבל אגבא אפי׳ כטרפא דאסא טריפה.</p>","notation":["ת׳"]},"35174":{"h":"גּוֹאֲלָה","r":"KRU03713","alt":[],"source":"krupnik","glosses":[{"text":"Redeemer","label":""}],"html":"<p>גואל Redeemer  קה״ר ד׳ א׳ (ושבתי): תרין אמורין חד אמר גולה וחד אמר גואלה וכו׳ ומ״ד גואלה פריקה.</p>","notation":["ז׳"]},"35175":{"h":"גּוּאַלְקָא","r":"KRU03714","alt":[],"source":"krupnik","glosses":[{"text":"haversack","label":""}],"html":"<p>שק, אמתחת haversack  תעני׳ כ״ג ע״ב: הבו לי גואלקא וכו׳.</p>","notation":["ז׳"]},"35176":{"h":"גּוּב","r":"KRU03716","alt":[],"source":"krupnik","glosses":[{"text":"to reply","label":"גַּיּיֵב פַעל"}],"html":"<p>גַּיּיֵב פַעל השיב, ענה to reply  ב״ר פ׳: ואי שאילנא ליה מגייב.\nאָגֵיב אפע׳, כנ״ל. ירוש׳ ברכ׳ א׳ ג׳ ע״ב: מגיב ליה חבריה. </p>","notation":[]},"35177":{"h":"גּוֹב","r":"KRU03717","alt":[],"source":"krupnik","glosses":[{"text":"pit","label":""},{"text":"out of","label":""}],"html":"<p>בור pit  דניא׳ ו׳ י״ג: יתרמא לגוב אריותא. מִן גּוֹבֵי־ מה״י מן, מתוך, out of  ירוש׳ כתו׳ י״ב ל״ה ע״א: ומן גוביהן עבד תלת עשרה שנין חשיש שינוי. </p>","notation":["ז׳","Marked biblical in source"]},"35178":{"h":"גּוּב²","r":"KRU03718","alt":[],"source":"krupnik","glosses":[{"text":"pit","label":"1"},{"text":"height, top","label":"2"},{"text":"body, trunk, untrimmed log Körper, Scheit, Stück","label":"3"}],"html":"<p>1 בור pit  תרג׳ שמו׳ כ״א ל״ג (וכי יפתח איש בור): וארי יפתח גבר גוב.\n2 מקום גבוה, גובה height, top  תרג׳ משלי ט׳ ג׳ (על־גפי): על גוב רמאתא.\n3 גוף, חתיכה body, trunk, untrimmed log Körper, Scheit, Stück ב״ק צ״ו ע״א: גובי דדיקלא; שבת ק״ט ע״ב: רב שימי בר אשי בלע חיויא וכו׳ ונפק מינה גובי גובי.</p>","notation":["ז׳"]},"35179":{"h":"גּוֹבָא","r":"KRU03720","alt":[],"source":"krupnik","glosses":[{"text":"locust","label":""}],"html":"<p>ארבה locust  תרג׳ שמו׳ י׳ ד׳ (הנני מביא מחר ארבה): אנא מיתי מחר גובא.</p>","notation":["ז׳"]},"35180":{"h":"גובאה","r":"KRU03721","alt":[],"source":"krupnik","glosses":[{"text":"height","label":""}],"html":"<p>גובה height  תרג׳ איוב ה׳ ז׳ (ובני רשף יגביהו עוף): בגובהא (בהו׳ אח׳: בגובאה צ״ל בגובהא) יטוסון.</p>","notation":["ז׳","Source emendation: גוֹבְהָא"]},"35181":{"h":"גּוֹבַאי","r":"KRU03722","alt":["גּוֹבָאִי"],"source":"krupnik","glosses":[{"text":"species of edible locusts","label":""}],"html":"<p>מין ארבה הנאכל species of edible locusts  שבת ל״ב ע״ב: בעון גזל הגובאי עולה והרעב הווה; תרג׳ תהל׳ ק״ה ל״ד (אמר ויבא ארבה): אמר ואיתי גובאי.</p>","notation":[]},"35182":{"h":"גּוֹבָאֵי","r":"KRU03723","alt":[],"source":"krupnik","glosses":[{"text":"inhabitants of Gobaya","label":""}],"html":"<p>תושבי עיר גּוֹבַיָּה בבבל inhabitants of Gobaya  קידוש׳ ע׳ ע״ב: גובאי גבעונאי דורנוניתא.</p>","notation":[]},"35183":{"h":"גּוֹבְבָתָא","r":"KRU03724","alt":[],"source":"krupnik","glosses":[{"text":"hills, esp. Gob’batha near Sepphoris","label":""}],"html":"<p>גבעות hills, esp. Gob’batha near Sepphoris  ב״ר צ״ח: אילין גובבתא דציפורין וכו׳.</p>","notation":["נ״ר"]},"35184":{"h":"גּוֹבַהּ","r":"KRU03725","alt":[],"source":"krupnik","glosses":[{"text":"height, elevation","label":""}],"html":"<p>רום, מקום גבוה height, elevation  מנח׳ ל״ז ע״ב גובה שביד; קיד׳ כ״א ע״ב: אין נרצע אלא בגובה של אזן.</p>","notation":["ז׳"]},"35185":{"h":"גּוֹבַיָּא","r":"KRU03728","alt":[],"source":"krupnik","glosses":[{"text":"a Babylonian place","label":""}],"html":"<p>שם מקום בבבל a Babylonian place  קיד׳ ע״ב ע״א: שוניא וגוביא.</p>","notation":[]},"35186":{"h":"גּוֹבַיְינָא","r":"KRU03730","alt":[],"source":"krupnik","glosses":[{"text":"collection","label":""}],"html":"<p>גביה collection  יבמ׳ ס״ו ע״ב: מחוסר גוביינא.</p>","notation":["ז׳"]},"35187":{"h":"גּוּבִּיתָא","r":"KRU03731","alt":[],"source":"krupnik","glosses":[{"text":"a low fence","label":""}],"html":"<p>גדר נמוך a low fence  ירוש׳ ערלה ג׳ ס״ג ע״ב: עבר חנין גוביתא ועקרין.</p>","notation":["נ׳"]},"35188":{"h":"גּוֹבֶל","r":"KRU03732","alt":[],"source":"krupnik","glosses":[{"text":"border of the field, ridge","label":""}],"html":"<p>שפת הערוגה border of the field, ridge  ירוש׳ כלא׳ פ״ג מ״א: היה לו גבול (בכ״י מינכן גובל) גבוה טפח.</p>","notation":["ז׳"]},"35189":{"h":"גּוּבְלָא","r":"KRU03733","alt":[],"source":"krupnik","glosses":[{"text":"a thick dough-like mass","label":""}],"html":"<p>בלילה עבה כמין בצק a thick dough-like mass  בר׳ ל״ח ע״א: גובלא בעלמא הוא.</p>","notation":["ז׳"]},"35190":{"h":"גּוּבְלָאֵי","r":"KRU03734","alt":[],"source":"krupnik","glosses":[{"text":"of Gabla, Idumeans","label":""}],"html":"<p>תושבי גַּבְלָא סמוך לירושלם of Gabla, Idumeans  תרג׳ תהל׳ פ״ג ח׳ (גבל ועמון): גובלאי ועמונאי.</p>","notation":["ז״ר"]},"35191":{"h":"גּוּבְלָנָא","r":"KRU03736","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ ע״ז ב׳ מ״א ע״ג: ר׳ ירמיה אזל לגובלנא.</p>","notation":[]},"35192":{"h":"גּוּבְנָא","r":"KRU03737","alt":[],"source":"krupnik","glosses":[{"text":"cheese","label":""}],"html":"<p>גבינה cheese  ירוש׳ מ״ק ג׳ פ״ג ע״א: אף על גב דאכל גובנא ושתא מיא.</p>","notation":["ז׳"]},"35193":{"h":"גּוֹבָנִי","r":"KRU03738","alt":[],"source":"krupnik","glosses":[{"text":"inhabitant of Gobaya","label":""}],"html":"<p>תושב עיר או מחוז גוביא inhabitant of Gobaya  ירוש׳ כתוב׳ י״ב ל״ה ע״א: חמתיה גובני ולא אתכנע מן קומוי.</p>","notation":["ז׳"]},"35194":{"h":"גּוּבְרָא","r":"KRU03740","alt":[],"source":"krupnik","glosses":[{"text":"strength, skill","label":"1"},{"text":"man, husband","label":"2"}],"html":"<p>1 כח strength, skill  נדה כ״ה ע״ב: רב גובריה.\n2 איש, בעל man, husband  ירוש׳ נזיר ח׳ נ״ו ע״ג: הא אזיל גוברא; תרג׳ קהל׳ ה׳ י״א: היכמא דלא שבקת איתתא לגוברא.</p>","notation":["ז׳"]},"35195":{"h":"גּוּבְשָׁא","r":"KRU03741","alt":[],"source":"krupnik","glosses":[{"text":"hill, mound","label":""}],"html":"<p>גבשושית hill, mound  תרג׳ צפני׳ א׳ י׳: ותברא רבא מן גבעתא (רד״ק: גובשתא).</p>","notation":["נ׳"]},"35196":{"h":"גּוּבְתָּא","r":"KRU03742","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ספרי במד׳ קל״א: גובתא דאריח.</p>","notation":["נ׳"]},"35197":{"h":"גּוּבְתָּא²","r":"KRU03743","alt":[],"source":"krupnik","glosses":[{"text":"tube","label":""}],"html":"<p>צנור, תעלה tube  בר׳ י״ח ע״ב: גובתא דכוחלא; יבמ׳ ע״ה ע״ב: גובתא דשכבת זרע.</p>","notation":["נ׳"]},"35198":{"h":"גּוֹגַּלְתָּא","r":"KRU03745","alt":[],"source":"krupnik","glosses":[{"text":"skull, head","label":""}],"html":"<p>גולגולת, ראש skull, head  תרג׳ שני אסתר ג׳ ט׳: סלעא דגוגלתא.</p>","notation":["נ׳"]},"35199":{"h":"גּוּגְמֵי","r":"KRU03746","alt":[],"source":"krupnik","glosses":[{"text":"stone-like peas","label":""}],"html":"<p>מין קטניות קשות כאבן stone-like peas  הורי׳ י״ג ע״א: אפילו גלימי (בערוך: גוגמי) גייצי.</p>","notation":["ז״ר"]},"35200":{"h":"גּוֹד","r":"KRU03747","alt":[],"source":"krupnik","glosses":[{"text":"leather bag, large leather bottle","label":""}],"html":"<p>נאד עשוי מעור leather bag, large leather bottle  שבת קל״ח ע״א: הגוד והמשמרת וכו׳ לא יעשה ואם עשה פטור (בכ״י מינכן הנוד).</p>","notation":["ז׳"]},"35201":{"h":"גּוּד","r":"KRU03748","alt":[],"source":"krupnik","glosses":[{"text":"to form bands, factions","label":""},{"text":"same","label":""}],"html":"<p>עשה אגודות אגודות to form bands, factions  יבמ׳ י״ג ע״ב: א״כ לימא קרא לא תגודו וכו׳. הִתְגּוֹדֵד התפ׳, נבדל ונפרד חבורות חבורות same  שם י״ד ע״א: כי אמרינן לא תתגודדו וכו׳. </p>","notation":["Marked biblical in source"]},"35202":{"h":"גּוּד אוֹ אָגּוֹד","r":"KRU03750","alt":[],"source":"krupnik","glosses":[{"text":"either fix you a price for my share or I shall do so (a legal form of discontinuing a companionship)","label":""}],"html":"<p>בחלוקת השותפין אם אין בדבר המשותף בכדי חלוקה לכל אחד יכול כל אחד מהשותפים לטעון: גוּד קח אתה הכל ופרע לי כנגד חלקי או אָגוֹד: אקח אני הכל ואפרע לך כנגד חלקך either fix you a price for my share or I shall do so (a legal form of discontinuing a companionship)  ב״ב י״ג ע״א: ר׳ יהודה אמר אית דינא דגוד או אגוד ר״נ אמר לית דינא דגוד או אגוד. ועי׳ גָּדַד.</p>","notation":[]},"35203":{"h":"גּוֹדָא","r":"KRU03751","alt":[],"source":"krupnik","glosses":[{"text":"leather bag","label":""}],"html":"<p>נאד leather bag  סוכ׳ מ״ח ע״ב: משוינן ליה גודא ומלינן ביה מיא; (שבת קל״ח ע״א: הגוד והמשמרת בכ״י מינכן: הנוד).</p>","notation":["ז׳"]},"35204":{"h":"גּוּדָא","r":"KRU03752","alt":[],"source":"krupnik","glosses":[{"text":"wall","label":"1"},{"text":"banks","label":"2"},{"text":"junction, joined boards","label":"3"},{"text":"a man’s name","label":"4"}],"html":"<p>1 כותל, מחיצה wall  ב״ב ב׳ ע״ב: אלא מאי גודא בונין את הכותל; קוה״ר י׳ ז׳ (ראיתי עבדים): טריף רישיה אגודא.\n2 שפת הנהר banks  תענ׳ כ״ד ע״ב: אנא הוה קאימנא אגודא דנהר פפא.\n3 נסרים אגודים יחד לעלות בהם ליבשה junction, joined boards  גיט׳ ע״ג ע״א: גודא דנימלא (כן בערוך, בהוצ׳: גודא דגמלי).\n4 שם איש a man’s name  ע״ז ל״ב ע״א: העיד שמעון בן גודא.</p>","notation":["נ׳"]},"35205":{"h":"גּוּדְגָּדָא","r":"KRU03753","alt":["גּוּדְגָּדָה"],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  חגי׳ פ״ב מ״ז: יוחנן בן גודגדא היה אוכל על טהרות הקודש; גיט׳ פ״ה מ״ה: העיד ר׳ יוחנן בן גודגדה וכו׳. </p>","notation":[]},"35206":{"h":"גּוּדְגַּדִּין","r":"KRU03754","alt":[],"source":"krupnik","glosses":[{"text":"good luck, Fortune","label":""}],"html":"<p>מזל, סימן אושר good luck, Fortune  תוס׳ צוק׳ שבת ו׳: המגבח לגודגדין.</p>","notation":["ז״ר"]},"35207":{"h":"גּוֹדֶל","r":"KRU03756","alt":[],"source":"krupnik","glosses":[{"text":"greatness","label":"1"},{"text":"pile","label":"2"}],"html":"<p>1 גדולה greatness  עיר׳ כ״א ע״ב: כבודי וגודלי.\n2 גל, ערֵמה pile  ירוש׳ ב״מ ב׳ ח׳ ע״ב: שלשתן של מלך אחד ועשויין גודלין.</p>","notation":["Marked biblical in source"]},"35208":{"h":"גּוּדָל","r":"KRU03757","alt":[],"source":"krupnik","glosses":[{"text":"thumb, great toe Daumen, grosse Zehe","label":""}],"html":"<p>בוהן (ביד וברגל) thumb, great toe Daumen, grosse Zehe שהש״ר ב׳ ד׳ (הביאני): וגודלו עלי אהבה; ירוש׳ ברכ׳ א׳ ב׳ ע״ג: היו מהלכין עקב בצד גודל וגודל בצד עקב.</p>","notation":["ז׳"]},"35209":{"h":"גּוֹדְלָנָא","r":"KRU03758","alt":[],"source":"krupnik","glosses":[{"text":"heap, the difference between stricken and heaped measure","label":""}],"html":"<p>גודש, ההבדל בין מדה גדושה ומדה מחוקה heap, the difference between stricken and heaped measure  ירוש׳ פסח׳ ד׳ ל״א ע״ג: אנא מחשבנא (צ״ל מחשכנא) גודלנא מן פורני.</p>","notation":["ז׳"]},"35210":{"h":"גּוֹדֶלֶת","r":"KRU03759","alt":[],"source":"krupnik","glosses":[{"text":"hair-dresser","label":""}],"html":"<p>שאומנותה לקלוע שערות hair-dresser  כלי׳ פט״ו מ״ג: ר׳ יהודה אומר אף של גודלות טמא מושב.</p>","notation":["נ׳"]},"35211":{"h":"גּוּדַּע","r":"KRU03761","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ע״ז ל״ב ע״ב: העיד שמעון בן גודע וכו׳. </p>","notation":["שם איש"]},"35212":{"h":"גּוֹדְפָן","r":"KRU03762","alt":[],"source":"krupnik","glosses":[{"text":"blasphemer","label":""}],"html":"<p>מגדף blasphemer  ירוש׳ יומא ז׳ מ״ד ע״ג: על הגודפנין וכו׳.</p>","notation":["ז׳"]},"35213":{"h":"גּוֹדְרוֹת","r":"KRU03763","alt":[],"source":"krupnik","glosses":[{"text":"moving live stock","label":""}],"html":"<p>צאן moving live stock  ב״ב ל״ו ע״א: הגודרות אין להם חזקה.</p>","notation":["נ״ר"]},"35214":{"h":"גּוּדְרִיתָא","r":"KRU03764","alt":[],"source":"krupnik","glosses":[{"text":"partition","label":""}],"html":"<p>גדר partition  עיר׳ י״ט ע״ב: גודריתא דקני מאי.</p>","notation":["נ׳"]},"35215":{"h":"גּוֹדֶשׁ","r":"KRU03765","alt":[],"source":"krupnik","glosses":[{"text":"the heap, the top over the level of a dry measure","label":""}],"html":"<p>החלק היותר על המדה the heap, the top over the level of a dry measure  זבחי׳ ס״ב ע״ב: כמחק גודש סאה.</p>","notation":["ז׳"]},"35216":{"h":"גּוּהָא","r":"KRU03767","alt":[],"source":"krupnik","glosses":[{"text":"a subterranean thunder, earthquake","label":""}],"html":"<p>רעם ורעש, קול שאון עולה ממעמקים a subterranean thunder, earthquake  ברכ׳ נ״ט ע״א: גוהא גוהא עביד (בכ״י מינכן: גיהא גיהא).</p>","notation":["ז׳"]},"35217":{"h":"גּוּהַרְקָא","r":"KRU03769","alt":[],"source":"krupnik","glosses":[{"text":"a carriage used by persons of distinction","label":"1"},{"text":"sour and hard berry","label":"2"}],"html":"<p>1 אפריון a carriage used by persons of distinction  תעני׳ כ׳ ע״ב: ביומא דעיבא הוו מפקין ליה בגוהרקא דדהבא.\n2 בוסר sour and hard berry  פס׳ כ״ה ע״ב: גוהרקי דערלה.</p>","notation":["ז׳"]},"35218":{"h":"גַּוָּוזָא","r":"KRU03772","alt":[],"source":"krupnik","glosses":[{"text":"stem, trunk","label":"1"},{"text":"eunuch, guardsman","label":"2"}],"html":"<p>1 גזיר עץ, ענף, גזע stem, trunk  ברכ׳ מ׳ ע״א: היכא מברכינן בורא פרי העץ היכא דכי שקלת ליה לפירי איתי לגווזא והדר מפיק; נדה ח׳ ע״ב: קטפא דגווזא; נדר׳ נ׳ ע״א: ולא אשכחו אלא גווזא וכו׳; חול׳ ח׳ ע״ב: פסיק ביה גווזא לע״ז.\n2 סריס eunuch, guardsman  קיד׳ ל״ג ע״א: משדר גוזאי.</p>","notation":["ז׳"]},"35219":{"h":"גַּוָּון","r":"KRU03777","alt":["גַּוָּן","גַּוְנָא","גַּוְונָא"],"source":"krupnik","glosses":[{"text":"surface, color, resemblance","label":""},{"text":"like, similar, for example","label":""},{"text":"like this, in a case like this","label":""}],"html":"<p>צבע, מראה פנים surface, color, resemblance  עיר׳ נ״ג ע״ב: מה גוון טליתך; נדה כ״ד ע״ב: בחד גוונא היה קאי; תרג׳ אסת׳ א׳ ו׳: גון חיור. כְּגוֹן כעין, כמו, למשל like, similar, for example  פסח׳ קי״ט ע״ב: כגון תמרים וכו׳. כִּי הַאי גּוֹנָא (כה״ג) כעין זה, בדרך זה like this, in a case like this  ב״מ ל׳ ע״ב: ומי הוי הפקר כי האי גונא; שם ס״ט ע״ב: כה״ג וכ׳. </p>","notation":[]},"35220":{"h":"גִּוֵון","r":"KRU03778","alt":[],"source":"krupnik","glosses":[{"text":"to color","label":"פיעל"}],"html":"<p>פיעל צבע to color  שבת ק״מ ע״א: אין עושין אותן אלא לגוון.</p>","notation":["פ״י"]},"35221":{"h":"גּוּז","r":"KRU03779","alt":[],"source":"krupnik","glosses":[{"text":"to cut, to cut off","label":""},{"text":"to annul","label":""},{"text":"to cross","label":""},{"text":"to carry across, to bring on","label":""}],"html":"<p>1) חתך, הפסיק to cut, to cut off  סנה׳ ק״י ע״א: דגייז למיזייכו. 2) ביטל to annul  נדר׳ ס״ח ע״א: בעל מיגז גייז. 3) עבור דרך־ to cross  ויק״ר ל״ז: מן דגייזין. אָגֵּיז אפ׳ העביר, המציא to carry across, to bring on  ב״ר י׳: ומגיזה יתיה נהרא; תרג׳ ירוש׳ במד׳ כ״א ה׳: ואגיזת להון סלווא. </p>","notation":["Marked biblical in source"]},"35222":{"h":"גּוּזָא","r":"KRU03780","alt":[],"source":"krupnik","glosses":[{"text":"chest, money chest","label":""}],"html":"<p>תבה קטנה למעות chest, money chest  נדר׳ נ׳ ע״א: הוה מחת בההוא גוזא (עי׳ רש״י. שם ועי׳ גווזא 1.)</p>","notation":["ז׳"]},"35223":{"h":"גּוֹזָא","r":"KRU03781","alt":[],"source":"krupnik","glosses":[{"text":"Goza, a river in Babylon","label":""}],"html":"<p>שם נהר בבבל Goza, a river in Babylon  ע״ז ל״ט ע״א: נהר גוזא.</p>","notation":[]},"35224":{"h":"גּוֹזְזִין","r":"KRU03783","alt":[],"source":"krupnik","glosses":[{"text":"cut wool","label":""}],"html":"<p>חתיכות cut wool  תרג׳ יחז׳ כ״ז כ״ד (גלומי): גוזזין.</p>","notation":["ז״ר"]},"35225":{"h":"גּוֹזָל","r":"KRU03784","alt":[],"source":"krupnik","glosses":[{"text":"brood, trnsf. young child","label":""}],"html":"<p>בהשאלה: ילד קטן brood, trnsf. young child  פסח׳ מ״ט ע״א: כל תלמיד חכם המרבה סעודתו וכו׳ מייתם את גוזליו ותלמודו משתכח ממנו.</p>","notation":["Marked biblical in source"]},"35226":{"h":"גּוֹזָלָא","r":"KRU03785","alt":[],"source":"krupnik","glosses":[{"text":"pigeon","label":""}],"html":"<p>גוזל pigeon  ירוש׳ ב״מ א׳ ח׳ ע״א: אשכח גוזלין ונסתון.</p>","notation":["ז׳"]},"35227":{"h":"גּוֹזְלָן","r":"KRU03786","alt":[],"source":"krupnik","glosses":[{"text":"robber","label":""}],"html":"<p>גזלן robber  ירוש׳ קיד׳ א׳ ס׳ ע״ג: כל המשנה מדעת הבעלים נקרא גוזלן.</p>","notation":["ז׳"]},"35228":{"h":"גּוּזְמָא","r":"KRU03787","alt":[],"source":"krupnik","glosses":[{"text":"hyperbole","label":""}],"html":"<p>הפרזה hyperbole  ערכ׳ י״א ע״א: מתניתא גוזמא.</p>","notation":["נ׳"]},"35229":{"h":"גַּוְזַנְיָא","r":"KRU03788","alt":[],"source":"krupnik","glosses":[{"text":"a fictitous place (Eunuchia)","label":""}],"html":"<p>שם מקום מדומה a fictitous place (Eunuchia)  שבת קנ״ב ע״א: אמר ליה ההוא גוזאה לר׳ יהושע בן קרחה מהכי לקרחינא כמה הוי אמר ליה כמהכא לגוזניא.</p>","notation":["ז״ר"]},"35230":{"h":"גּוֹזֵר","r":"KRU03789","alt":[],"source":"krupnik","glosses":[{"text":"circumciser","label":""}],"html":"<p>מוהל circumciser  שבת ק״ל ע״ב: שאילית את ר׳ יהודה הגוזר.</p>","notation":["ז׳"]},"35231":{"h":"גּוֹזְרָיָא","r":"KRU03790","alt":[],"source":"krupnik","glosses":[{"text":"circumciser or of Gezer","label":""}],"html":"<p>כנ״ל או ממקום ששמו גזר circumciser or of Gezer  ירוש׳ ר״ה ג׳ נ״ט ע״א: ר׳ יודה גוזריא.</p>","notation":["ז׳"]},"35232":{"h":"גּוּזַרְתָּא","r":"KRU03791","alt":[],"source":"krupnik","glosses":[{"text":"circumcision","label":""}],"html":"<p>מילה circumcision  תרג׳ יב״ע שמות ד׳ כ״ה: אדם גוזרתא.</p>","notation":["נ׳"]},"35233":{"h":"גּוּחֲכָא","r":"KRU03793","alt":[],"source":"krupnik","glosses":[{"text":"laughter","label":"1"},{"text":"sneer","label":"2"}],"html":"<p>1 שחוק laughter  תרג׳ משלי י״ד י״ג (גם בשחוק): אף בגוחכא נכאב ליבא.\n2 התול, לעג sneer  תרג׳ תהל׳ ע״ט ד׳: תולעבא וגוחכא לחזרנותנא.</p>","notation":["ז׳"]},"35234":{"h":"גּוֹי","r":"KRU03795","alt":[],"source":"krupnik","glosses":[{"text":"gentile, idolator","label":""}],"html":"<p>אינו יהודי, עכו״ם, נכרי gentile, idolator  ירוש׳ יבמ׳ ב׳ ד׳ ע״א: גוי שבא על גויה.</p>","notation":["Marked biblical in source"]},"35235":{"h":"גְּוִי","r":"KRU03796","alt":[],"source":"krupnik","glosses":[{"text":"to fathom","label":""}],"html":"<p>העמיק to fathom  עירוב׳ ס״א ע״ב: גוו ביה טפי.</p>","notation":["פ״י"]},"35236":{"h":"גְּוִיָּא","r":"KRU03798","alt":[],"source":"krupnik","glosses":[{"text":"inner body","label":""}],"html":"<p>גוף inner body  תרג׳ יחז׳ א׳ י״א (את גויתהנה): גויתהן.</p>","notation":["ז׳"]},"35237":{"h":"גּוֹיָה","r":"KRU03799","alt":[],"source":"krupnik","glosses":[{"text":"gentile woman","label":""}],"html":"<p>אינה יהודית gentile woman  ירוש׳ סנה׳ ט׳ כ״ז ע״ב: זה שהוא נושא גויה.</p>","notation":["ז׳"]},"35238":{"h":"גְּוִיָּה","r":"KRU03800","alt":[],"source":"krupnik","glosses":[{"text":"creature","label":"1"},{"text":"membrum virile","label":"2"}],"html":"<p>1 בריה creature  ירוש׳ ברכ׳ ד׳ ח׳: שתתן לכל בריה ובריה צרכיה ולכל גויה וגויה די מחסורה.\n2 אבר הזכרות membrum virile  נגעי׳ פ״ו מ״ז: עשרים וארבעה ראשי איברין באדם וכו׳ וראשי הגויה וכו׳.</p>","notation":["Marked biblical in source"]},"35239":{"h":"גְּוִיָּיה","r":"KRU03801","alt":[],"source":"krupnik","glosses":[{"text":"body, cadaver","label":"1"}],"html":"<p>1 גוף, פגר body, cadaver  תוס׳ אהל׳ ג׳ ד׳: רובע עצמות מרוב הגוייה מרוב הבנין; מו״ק כ״ד ע״א: ומעשה באחד וכו׳ ושמטו חזרים את גוייתו.\n2 עי׳ גְּוִיָּה 2. קידוש׳ כ״ה ע״א: דגיד היינו גוייה. </p>","notation":["Marked biblical in source"]},"35240":{"h":"גְּוִיְיתָא","r":"KRU03802","alt":[],"source":"krupnik","glosses":[{"text":"body","label":""}],"html":"<p>גוף body  תרג׳ יב״ע ברא׳ ז׳ כ״ג (וימח את כל היקום): גויית אינש ובעיר.</p>","notation":["ז׳"]},"35241":{"h":"גְּוִיל","r":"KRU03803","alt":[],"source":"krupnik","glosses":[{"text":"rough untrimmed stone, cobble","label":"1"},{"text":"a roll of parchment, a certain kind of parchment","label":"2"}],"html":"<p>1 אבן לא מסותתה rough untrimmed stone, cobble  ב״ב פ״א מ״א: מקום שנהגו לבנות גויל גזית וכו׳ בונים הכל כמנהג המדינה.\n2 מגילה, קלף שאינו מעובד כל צרכו a roll of parchment, a certain kind of parchment  ע״ז י״ח ע״א: גוילין נשרפין ואותיות פורחות; מו״ק כ״ו ע״א: הרואה ס״ת שנשרף חייב לקרוע שתי קריעות א׳ על הגויל וא׳ על הכתב; שבת ע״ט ע״ב: כתבה על הקלף ועל הגויל וכו׳ כשרה.</p>","notation":["ז׳"]},"35242":{"h":"גְּוִיעָה","r":"KRU03805","alt":[],"source":"krupnik","glosses":[{"text":"expiration","label":""}],"html":"<p>מיתה expiration  ב״ב ט״ז ע״א: כל מיתה שיש בה גויעה זו הוא מיתתן של צדיקים.</p>","notation":["נ׳"]},"35243":{"h":"גְּוִיתָא","r":"KRU03806","alt":[],"source":"krupnik","glosses":[{"text":"body","label":""}],"html":"<p>גוף body  תרג׳ בר׳ מ״ז י״ח (בלתי אם גויתנו): אלהן גויתנא.</p>","notation":["ז׳"]},"35244":{"h":"גּוּל","r":"KRU03807","alt":[],"source":"krupnik","glosses":[{"text":"to roll up a scroll of the Law","label":""}],"html":"<p>גלל to roll up a scroll of the Law  ירוש׳ מגי׳ ד׳ ע״ה ע״ב: שאין גולים (צ״ל גלים) ספר תורה ברבים.</p>","notation":["Marked biblical in source"]},"35245":{"h":"גּוֹל","r":"KRU03808","alt":[],"source":"krupnik","glosses":[{"text":"clapper of a bell","label":""}],"html":"<p>לשון הפעמון clapper of a bell  תנחומ׳ אמור ה׳: והגול שלו מן מרגלית (בהוצ׳ בובר גיל.)</p>","notation":["ז׳"]},"35246":{"h":"גּוּלָאֵי","r":"KRU03810","alt":[],"source":"krupnik","glosses":[{"text":"persons of the same age and circle","label":""}],"html":"<p>בני גיל אחד persons of the same age and circle  זבח׳ קט״ז ע״ב: תרי עולמי גולאי, ועי׳ גִּילָאֵי.</p>","notation":["ז״ר"]},"35247":{"h":"גּוּלְבָּא","r":"KRU03811","alt":[],"source":"krupnik","glosses":[{"text":"spelt","label":""}],"html":"<p>מין תבואה, כוסמין spelt  פסח׳ ל״ה ע״א: כוסמין — גולבא.</p>","notation":["ז׳"]},"35248":{"h":"גּוּלְבִּינָא","r":"KRU03812","alt":[],"source":"krupnik","glosses":[{"text":"a species of peas","label":""}],"html":"<p>מין קטניות a species of peas  ירוש׳ כלא׳ א׳ כ״ז ע״א: גולבינא.</p>","notation":["ז׳"]},"35249":{"h":"גּוּלְגּוֹלֶת","r":"KRU03813","alt":[],"source":"krupnik","glosses":[{"text":"scull, head","label":"1"},{"text":"capitation tax","label":"2"}],"html":"<p>1 ראש, כלל עצמות הראש המקיפים את המח scull, head  אבות פ״ב מ״ו: אף הוא ראה גולגולת אחת שצפה על פני המים.\n2 מכס המשתלם לפי מכסת נפשות capitation tax  ירוש׳ כתוב׳ י״ג ל״ה ע״ד: אין לך נתפס על חבירו וחייב ליתן לו אלא בארני ובגולגולת.</p>","notation":["נ׳,","Marked biblical in source"]},"35250":{"h":"גולגוקין","r":"KRU03814","alt":[],"source":"krupnik","glosses":[{"text":"Roman) shoes, which leave the toes uncovered","label":""}],"html":"<p>מין נעלים (Roman) shoes, which leave the toes uncovered  ירוש׳ ביצה ה׳ ס״ג ע״א: אצבעתיה דר׳ מן גולגוקין דידיה.</p>","notation":["ז״ר","Source emendation: גַּלְגְּיוֹלִין"]},"35251":{"h":"גולגסיים","r":"KRU03819","alt":[],"source":"krupnik","glosses":[{"text":"nail-studded shoe of the Roman soldiers","label":""}],"html":"<p>סנדלים המסומרים של חילי רומי nail-studded shoe of the Roman soldiers  איכ״ר ב׳ ז׳ (זנח ד׳): ועשו מסגר של גליאסין (צ״ל ועשו מסמרות של גליגאסין: בערוך: ועשו רושם במסמרות הגלוגסיים).</p>","notation":["ז״ר","Source emendation: גַּלִּגָאסִין"]},"35252":{"h":"גּוֹלָה","r":"KRU03821","alt":[],"source":"krupnik","glosses":[{"text":"chief of the Babylonian Jews","label":""}],"html":"<p>רֹאשׁ גּוֹלָה, הראש שהיה ממונה על היהודים בבבל chief of the Babylonian Jews  סנה׳ ל״ח ע״א: שני בתי אבות מישראל ואלו הן ראש גולה שבבבל ונשיא שבארץ ישראל</p>","notation":["Marked biblical in source"]},"35253":{"h":"גּוּלְיָיר","r":"KRU03824","alt":[],"source":"krupnik","glosses":[{"text":"common soldier","label":""}],"html":"<p>איש צבא, חיָל פשוט common soldier  ב״ר ס״ג: ולא בגולייר זעיר; נזיר ס״ו ע״ב: תדע שהרי גוליירים מתגרין במלחמה וגבורים נוצחים.</p>","notation":["ז׳"]},"35254":{"h":"גּוּלִילָא","r":"KRU03825","alt":[],"source":"krupnik","glosses":[{"text":"threshing roller","label":""}],"html":"<p>מורג threshing roller  תרג׳ מ״א י״ד י׳ (כאשר יבער הגלל): כמא דמגנדרין בגולילין.</p>","notation":["ז׳"]},"35255":{"h":"גּוֹלְיְתָא","r":"KRU03827","alt":[],"source":"krupnik","glosses":[{"text":"a long woolen cloak of state used at prayers","label":""}],"html":"<p>בגד, טלית a long woolen cloak of state used at prayers  תרג׳ יב״ע במדבר ט״ו ל״ח (על כנפי בגדיהם): אנפא גוליתהון. ועי׳ גּוֹלְתָא.</p>","notation":["נ״ר"]},"35256":{"h":"גּוֹלֵל","r":"KRU03829","alt":["גּוֹלְלָא"],"source":"krupnik","glosses":[{"text":"the stone placed on the top of a burial place","label":""}],"html":"<p>לוח עגול של אבן לסגור בו את פתח מערת הכוכים (הקברים) the stone placed on the top of a burial place  אהל׳ פ״ב מ״ד: איזהו הדופק כל שהגולל נשען עליו; תרג׳ איוב י״ד כ״ב (אך בשרו): עד דלא יסתתים גוללא עלוהי כאב.</p>","notation":[]},"35257":{"h":"גּוֹלֶם","r":"KRU03830","alt":[],"source":"krupnik","glosses":[{"text":"a shapeless mass","label":"1"},{"text":"unfinished vessel","label":"2"},{"text":"body","label":"3"},{"text":"uneducated, unrefined","label":"4"}],"html":"<p>1 גוש בלי תואר וצורה a shapeless mass  ירוש׳ נדה ג׳ נ׳ ע״ד: רואין שתי זרועותיו (של העובר) כמין שני חוטין של זהורית ושאר כל אבריו כמין גולם.\n2 כלי שלא נגמרה מלאכתו unfinished vessel  סנה׳ כ״ב ע״ב: אשה גולם היא וכו׳.\n3 גוף body  ילקו׳ במדב׳ תשע״א: בשני גולמין.\n4 בהשאלה: אדם נבער משכל, הדיוט uneducated, unrefined  אבו׳ פ״ה מ״ז: וחלופיהן בגולם.</p>","notation":["Marked biblical in source"]},"35258":{"h":"גּוֹלְמָא","r":"KRU03831","alt":[],"source":"krupnik","glosses":[{"text":"stone","label":"2"},{"text":"hill","label":"3"}],"html":"<p>1 כנ״ל 2. שבת קכ״ג ע״א: בגולמי עסקינן. \n2 אבן stone  סנה׳ צ״ה ע״א: למחר אייתי לי כל חד וחד מינייכי גולמו הרג מיניה מיד (צ״ל: אייתי לי וכו׳ גולמא ונירגמינה מיד).\n3 גבעה hill  תרג׳ תהל׳ ע״ב ג׳: (וגבעות בצדקה): וגלמתא בזכותא.</p>","notation":["ז׳"]},"35259":{"h":"גּוֹלָמִי","r":"KRU03833","alt":["גּוֹלָמִית"],"source":"krupnik","glosses":[{"text":"unshaped","label":""}],"html":"<p>בלי צורה unshaped  שמו״ר ל׳: מצות גלומות (הוצ׳ אח׳: גולמיות).</p>","notation":["ז׳"]},"35260":{"h":"גּוֹלָמִישׁ","r":"KRU03834","alt":[],"source":"krupnik","glosses":[{"text":"a species of cedar","label":""}],"html":"<p>מין ארז a species of cedar  ר״ה כ״ג ע״א: ואמרי לה זו גולמיש.</p>","notation":["ז׳"]},"35261":{"h":"גּוֹלָנִית","r":"KRU03835","alt":[],"source":"krupnik","glosses":[{"text":"a coin named after Golan in Bashan","label":""}],"html":"<p>מטבע מגולן בבשן a coin named after Golan in Bashan  תוס׳ מעש״ש ד׳ י״ג: גולנית (הוצ׳ צוקרמנדל: נולגית).</p>","notation":["נ׳"]},"35262":{"h":"גּוּלְפָא","r":"KRU03836","alt":[],"source":"krupnik","glosses":[{"text":"stone pitcher, jug","label":""}],"html":"<p>כד, קנקן של חרס stone pitcher, jug  יומא י״ב ע״א: אורח ארעה למישבק איניש גולפא ומשכא לאושפיזיה.</p>","notation":["ז׳"]},"35263":{"h":"גּוֹלְתָא","r":"KRU03838","alt":["גּוֹלְתָה"],"source":"krupnik","glosses":[{"text":"a long woolen cloak of state used at prayers","label":""}],"html":"<p>טלית, בגד a long woolen cloak of state used at prayers  ירוש׳ כלא׳ ט׳ ל״ב ע״ב: מהו מיתן פריטין גו גולתה; ב״מ פ״ח ע״א: אמר ליה חכים עבדו יתך וגולתא דדהבא פרסו עלך.</p>","notation":[]},"35264":{"h":"גּוֹמֶא","r":"KRU03841","alt":[],"source":"krupnik","glosses":[{"text":"bulrush, papyrus","label":""}],"html":"<p>מין קנה bulrush, papyrus  תרג׳ שמ׳ ב׳ ג׳ (תיבת גמא): תיבתא דגומא.</p>","notation":["Marked biblical in source"]},"35265":{"h":"גּוּמָא","r":"KRU03842","alt":[],"source":"krupnik","glosses":[{"text":"hole, indentation","label":""}],"html":"<p>נקב קטן, חור hole, indentation  ב״ב ט״ז ע״א: גומא בפני עצמה; ירוש׳ כתוב׳ א׳ כ״ה ע״ב: לעושה גומא וכו׳.</p>","notation":["נ׳"]},"35266":{"h":"גּוֹמֶד","r":"KRU03843","alt":[],"source":"krupnik","glosses":[{"text":"gomed, a length-measure","label":"1"},{"text":"a veil of a square gomed","label":"2"}],"html":"<p>1 מדה קצרה כזרוע gomed, a length-measure  ערכ׳ י״א ע״א וגובה (בערוך: וגמדה) אמה.\n2 מטלית ששמים הערבים על הפה להגן מפני הקור או האבק a veil of a square gomed  כלי׳ פכ״ט מ״א: והגומדין של ערביין.</p>","notation":["Marked biblical in source"]},"35267":{"h":"גּוּמִי","r":"KRU03844","alt":[],"source":"krupnik","glosses":[{"text":"gum, gum-tree","label":""}],"html":"<p>מין עץ (קומוס) gum, gum-tree  ירוש׳ שבת ז׳ י׳ ע״א: ההן דגזז ספוג גומי וכו׳.</p>","notation":["ז׳"]},"35268":{"h":"גּוּמָל","r":"KRU03846","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>(קיצור של גמליאל) a man’s name  מנח׳ נ״ד ע״ב: ואבא אלעזר גומל הוא (כ״י מינכן: גמל).</p>","notation":["שם איש"]},"35269":{"h":"גּוּמְלָא","r":"KRU03847","alt":[],"source":"krupnik","glosses":[{"text":"recompense","label":""}],"html":"<p>גמול recompense  תרג׳ תהל׳ צ״ד ב׳: אתיב גומלא בישא.</p>","notation":["ז׳"]},"35270":{"h":"גּוֹמָמִית","r":"KRU03848","alt":[],"source":"krupnik","glosses":[{"text":"hole, excavation","label":""}],"html":"<p>חור, גומא hole, excavation  ירוש׳ כלא׳ ג׳ כ״ח ע״ג: גוממיות שהן עמוקות טפח.</p>","notation":["ז׳"]},"35271":{"h":"גּוּמְצָא","r":"KRU03851","alt":[],"source":"krupnik","glosses":[{"text":"pit","label":""}],"html":"<p>גומא, שוחה pit  תרג׳ משלי כ״ג כ״ז (כי שוחה): דגומצא.</p>","notation":["זו״נ"]},"35272":{"h":"גּוּמְרָא","r":"KRU03852","alt":["גּוּמְרָה"],"source":"krupnik","glosses":[{"text":"glowing coal","label":""}],"html":"<p>גחלת בוערת glowing coal  ירוש׳ חגי׳ ב׳ ע״ח ע״א: כל גומרא דלא כוויא בשעתה לא כוויא (משל); ירוש׳ מעש״ש ה׳ נ״ו ע״ג: כל גומרה וכו׳.</p>","notation":[]},"35273":{"h":"גּוּמַרְתָּא","r":"KRU03853","alt":[],"source":"krupnik","glosses":[{"text":"a local skin-disease, (burn)","label":"2"}],"html":"<p>1 כנ״ל. חול׳ י״א ע״א: דמונח גומרתא. \n2 מין חולי (דלקת) a local skin-disease, (burn)  ירוש׳ ע״ז ב׳ מ׳ ע״ד: הדא גומרתא סכנה.</p>","notation":[]},"35274":{"h":"גּוּמְתָא","r":"KRU03854","alt":[],"source":"krupnik","glosses":[{"text":"pit","label":""}],"html":"<p>גומא pit  תרג׳ איוב ל״ט כ״ד (יגמא ארץ): יעביד גומתא בארעא.</p>","notation":["נ׳"]},"35275":{"h":"גּוּן","r":"KRU03856","alt":["הֵגִין"],"source":"krupnik","glosses":[{"text":"to protect","label":"הפ׳,"}],"html":"<p>הפ׳, היה למחסה to protect  סוט׳ י׳ ע״א: מה הקב״ה מגין על העולם וכו׳.</p>","notation":[]},"35276":{"h":"גּוֹנֶבֶת","r":"KRU03861","alt":[],"source":"krupnik","glosses":[{"text":"inclined to steal","label":""}],"html":"<p>ת״נ, שדרכה לגנוב inclined to steal  דב״ר ו׳: אמר הקב״ה לא אברא אותה (את האשה) וכו׳ מן היד שלא תהא גונבת.</p>","notation":[]},"35277":{"h":"גּוּנְדָּא","r":"KRU03862","alt":[],"source":"krupnik","glosses":[{"text":"a band, troop","label":""}],"html":"<p>גדוד a band, troop  ב״מ פ״ו ע״א: גונדא דפרשי; ברכו׳ נ״ח ע״א: חלף גונדא קמייתא.</p>","notation":["זו״נ"]},"35278":{"h":"גּוּנְדָּא²","r":"KRU03863","alt":[],"source":"krupnik","glosses":[{"text":"wall","label":"1"},{"text":"name of a domestic overall, duster","label":"2"}],"html":"<p>1 כותל wall  סוט׳ כ״ב ע״א: בי דינא רבה ליתפרע מהני דחפי גונדי (בערוך כן).\n2 מעפורת, אדרת שמתכסים בה להנצל מאבק name of a domestic overall, duster  שבת קי״ט ע״א: רב ענן לביש גונדא.</p>","notation":["נ׳"]},"35279":{"h":"גּוּנְדְלִית","r":"KRU03864","alt":[],"source":"krupnik","glosses":[{"text":"spiral form, writing in spiral form","label":""}],"html":"<p>בצורת בורג spiral form, writing in spiral form  גיט׳ פ״ז ע״ב: דילמא גונדלית חתים וכו׳ (ועי׳ רש״י שם.)</p>","notation":["נ׳"]},"35280":{"h":"גּוּנְדְרָא","r":"KRU03865","alt":[],"source":"krupnik","glosses":[{"text":"hard, stony cold","label":""}],"html":"<p>רגב, עפר hard, stony cold  ב״מ פ׳ ע״א: ואי דוכתא דמחזק׳ גונדרי (צ״ל: גרונדי) תרויהו משלמין.</p>","notation":["ז׳","Source emendation: גְּרוּנְרָא"]},"35281":{"h":"גּוּנְדְרִיתָא","r":"KRU03866","alt":[],"source":"krupnik","glosses":[{"text":"balustrade","label":""}],"html":"<p>גזוזטרה, מעקה balustrade  קידוש׳ ע׳ ע״א: א״ל פורתא דגונדריתא הוא דקא עבידנא.</p>","notation":["נ׳"]},"35282":{"h":"גּוּנִי","r":"KRU03867","alt":[],"source":"krupnik","glosses":[{"text":"woman","label":""}],"html":"<p>אשה woman  ב״ר י״ח: גוני גוניא.</p>","notation":["נ׳"]},"35283":{"h":"גּוּנְיָא","r":"KRU03868","alt":[],"source":"krupnik","glosses":[{"text":"man","label":""}],"html":"<p>איש man  שם: גוני גוניא אנתרופי אנתרופיא גברא גברתא – אלא איש ואשה. ועי׳ גְּבַרְתָּא.</p>","notation":["ז׳"]},"35284":{"h":"גּוּנְכָא","r":"KRU03870","alt":[],"source":"krupnik","glosses":[{"text":"bed-cloth, blanket","label":""}],"html":"<p>שמיכה bed-cloth, blanket  תרג׳ שופ׳ ד׳ י״ח (ותכסהו בשמיכה): וכסיתיה בגונכא.</p>","notation":["ז׳"]},"35285":{"h":"גּוּנְתָּאִי","r":"KRU03871","alt":[],"source":"krupnik","glosses":[{"text":"a Goth","label":""}],"html":"<p>בן עם הגותים a Goth  איכ״ר ב׳ ב׳ (בלע ד׳): א״ל חד גונתאי אנא קטלתיה לדין.</p>","notation":["ז׳"]},"35286":{"h":"גּוּס","r":"KRU03873","alt":[],"source":"krupnik","glosses":[{"text":"verbunden)","label":""},{"text":"to embolden one's heart, to become bold","label":""},{"text":"to become bold","label":""}],"html":"<p>גדל, התגאה to swell, to be bold (gen. with לב) | anschwellen, hochmütig werden (gew. mit לב verbunden) כתו׳ י״ב ע״א: כדי שיהא לבו גס בה; שם כ״ח ע״א: שאין לבו גס בה; גיט׳ פ״ז מ״ד: לבה גס בשפחתה. הֵגִיס הפ׳, עשה לבו גס (שלא יפקפק) to embolden one&#x27;s heart, to become bold  שמו״ר ו׳: מי הגיס את לבך; ירוש׳ מעש׳ ב׳ מ״ט ע״ג: להגיס את לבו שיאכל; ירוש׳ סנה׳ א׳ י״ח ע״א: הגיס דעתו לדון; ברכ׳ י״ט ע״א: והמגיס דעתו כלפי מעלה. אָגֵיס אפע׳ כנ״ל. תרג׳ יב״ע דבר׳ י״ז כ׳ (לבלתי רום לבבו): אגיס. אִתְגַּס אתפ׳ התגאה to become bold  תרג׳ דבהי״ב כ״ו ט״ז (גבה לבו): אתגס. </p>","notation":["פ״ע"]},"35287":{"h":"גּוּס²","r":"KRU03874","alt":[],"source":"krupnik","glosses":[{"text":"to stir","label":"הֵגִיס הפ׳,"}],"html":"<p>הֵגִיס הפ׳, סכסך ונער את הקדרה to stir  מכשי׳ פ״ה מי״א: מגיסה בקדרה; ביצ׳ ל״ד ע״א; אחד מביא את האור וכו׳ ואחד שופת את הקדרה וכו׳ ואחד מגיס.</p>","notation":["Source marks no qal form"]},"35288":{"h":"גּוּס³","r":"KRU03875","alt":[],"source":"krupnik","glosses":[{"text":"to meet","label":""}],"html":"<p>פגע ב.. to meet  גיט׳ ס״ה ע״ב: בהדי דקאזיל מיגס גאיס בה; פסח׳ ק״י ע״ב: גס ביה ההוא טייעא.</p>","notation":["פ״ע"]},"35289":{"h":"גּוּס⁴","r":"KRU03876","alt":[],"source":"krupnik","glosses":[{"text":"to dine","label":""}],"html":"<p>סעד to dine  אסת״ר א׳ ח׳ (והשתיה כדת): אית אתר דבעי מיגס ובתר כן שתי וכו׳.</p>","notation":["פ״ע"]},"35290":{"h":"גּוֹסֵסֹ","r":"KRU03879","alt":["גּוֹסֶסֶת"],"source":"krupnik","glosses":[{"text":"dying","label":""}],"html":"<p>נוטה למות, נלחם עם המות dying  שמח׳ א׳: הגוסס הרי הוא כחי לכל דבר; קידו׳ ע״א ע״ב: עילם גוססת.</p>","notation":["ז׳"]},"35291":{"h":"גָּוַע","r":"KRU03881","alt":[],"source":"krupnik","glosses":[{"text":"to diminish","label":""}],"html":"<p>החליש to diminish  תנחו׳ נח ז׳: והן גועו אותן וכו׳.</p>","notation":["פ״י","Marked biblical in source"]},"35292":{"h":"גּוּף","r":"KRU03882","alt":[],"source":"krupnik","glosses":[{"text":"to bung, to cork","label":"1"}],"html":"<p>1 סתם פי כלי to bung, to cork  נדה ו׳ ע״ב: מעשה בשפחה של רבן גמליאל שהיתה גפה חביות של יין.</p>","notation":["פ״י"]},"35293":{"h":"גִּיּיֵף","r":"KRU03883","alt":[],"source":"krupnik","glosses":[{"text":"to embrace","label":"פיעל,"},{"text":"to close","label":"הֵגִיף הפע׳,"}],"html":"<p>פיעל, חיבק to embrace  ירוש׳ יומא ג׳ מ״א ע״א: ועמד וגייפו.\nהֵגִיף הפע׳, סגר to close  זבח׳ פ״ג מ״ב: מגיפין או פותחין.</p>","notation":[]},"35294":{"h":"גּוּף²","r":"KRU03884","alt":[],"source":"krupnik","glosses":[{"text":"to close","label":""},{"text":"to commit adultery with","label":""},{"text":"to close","label":""}],"html":"<p>1) סגר to close  תרג׳ מלאכי א׳ י׳ (ויסגור): ויגוף ועי׳ הנ״ל. 2) נאף to commit adultery with  תרג׳ ויקר׳ כ׳ י׳ (אשר ינאף): יגוף. אָגֵיף אפ׳ סגר to close  ב״ק ק״ה ע״א: אגף חצייה. </p>","notation":["פ״י"]},"35295":{"h":"גּוּף³","r":"KRU03886","alt":[],"source":"krupnik","glosses":[{"text":"person, body, self","label":""},{"text":"personal duty","label":""},{"text":"trnsf. Guf, a fictitous storehouse of souls in heaven","label":""},{"text":"essence, substance","label":""},{"text":"membrum virile","label":""},{"text":"surface, color","label":""}],"html":"<p>1) גויה, החומר של החי person, body, self  ברכ׳ ה׳ ע״א: יסורין שממרקין כל גופו של אדם; אבות פ״ד מ״ו: גופו מכובד וכו׳. חוֹבַת הַגּוּף חובה המוטלת על האדם בעצמו personal duty  קיד׳ ל״ז ע״א: כל מצוה שהוא חובת הגוף נוהגת בין בארץ בין בח״ל. 2) בהשאלה: מקום דמיוני במרומים שאצורות בו הנשמות היעודות להנתן בגופות בני האדם בהולדם trnsf. Guf, a fictitous storehouse of souls in heaven  יבמ׳ ס״ב ע״א: אין בן דוד בא עד שיכלו כל נשמות שבגוף. 3) עצם הדבר essence, substance  ירוש׳ ברכ׳ א׳ ג׳ ע״ג: גופה של שמע. 4) אבר הזכרות membrum virile  ויק״ר כ״ה: ערלת הגוף. 5) צבע, מראה surface, color  מנח׳ מ״ד ע״א: גופו דומה לים. </p>","notation":["ז׳"]},"35296":{"h":"גּוּפָא","r":"KRU03887","alt":[],"source":"krupnik","glosses":[{"text":"body","label":""},{"text":"self, substance","label":""},{"text":"this contains a contradiction in itself","label":""}],"html":"<p>1) גוף body  איכ״ר א׳ א׳ (רבתי): נסב גופא כולה. 2) עיקר הדבר, הדבר בעצמו ולא הנוסף עליו self, substance  ביצה ג׳ ע״א: היא גופא גזירא וכו׳. הָא גּוּפָא קַשְׁיָא הלא יש סתירה בדבר this contains a contradiction in itself  נדה מ״ו ע״א: הא גופא קשיא אמרת אינה ממאנת. </p>","notation":["ז׳"]},"35297":{"h":"גּוּפָא²","r":"KRU03888","alt":[],"source":"krupnik","glosses":[{"text":"i>Zitierungsform in der talmudischen Diskussion, wenn ein vorher gelegentlich angeführter Ausspruch zum Hauptgegenstand der Erörterung werden soll","label":""}],"html":"<p>נחזור לעניננו (בתלמוד: אחרי שהופסק הענין ע״י שקלא וטריא) a talmudical term גוּפא used for taking up a text or subject after an interruption by a discussion: returning to our subject | גוּפא &lt;i&gt;Zitierungsform in der talmudischen Diskussion, wenn ein vorher gelegentlich angeführter Ausspruch zum Hauptgegenstand der Erörterung werden soll חול׳ ק״ה ע״א: גופא מים ראשונים וכו׳.</p>","notation":[]},"35298":{"h":"גּוֹפֶן","r":"KRU03889","alt":[],"source":"krupnik","glosses":[{"text":"character of letters","label":""}],"html":"<p>צורת האותיות character of letters  מג׳ ט׳ ע״א: בגופן שלנו (בעברית).</p>","notation":["ז׳"]},"35299":{"h":"גּוּפָן","r":"KRU03890","alt":[],"source":"krupnik","glosses":[{"text":"fennel","label":"1"},{"text":"late grapes","label":"2"}],"html":"<p>1 מין ירק שריחו עז fennel  תוס׳ כלא׳ פ״א מ״א: השבת והגופנין וכו׳.\n2 ענבים המאחרים להתבשל late grapes  ברכ׳ מ׳ ע״ב: שלהי גופני.</p>","notation":["ז׳"]},"35300":{"h":"גּוֹפַן","r":"KRU03891","alt":["גּוּפְנָא"],"source":"krupnik","glosses":[{"text":"vine, grape-vine","label":"1"},{"text":"the cotton-tree","label":"2"}],"html":"<p>1 גפן, ענב vine, grape-vine  תרג׳ (הוצא׳ ברלינר) ברא׳ מ״ט כ״ב: גופן (ת׳ יב״ע: גופֶן); תרג׳ יחז׳ י״ז ז׳: (והנה הגפן): והא גופנא.\n2 מין צמח שפריו מלא סיבי צמר רבים the cotton-tree  גיט׳ ס״ט ע״ב: ודעמר גופנא.</p>","notation":[]},"35301":{"h":"גּוֹפְנָא","r":"KRU03892","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ תענ׳ ד׳ ס״ט ע״א: גופנא.</p>","notation":[]},"35302":{"h":"גּוֹפֶר","r":"KRU03893","alt":[],"source":"krupnik","glosses":[{"text":"a resinous tree","label":""}],"html":"<p>עץ גופר a resinous tree  סנה׳ ק״ח ע״ב: מאי גופר וכו׳ מפליגה.</p>","notation":["Marked biblical in source"]},"35303":{"h":"גּוּפְרִיתָא","r":"KRU03894","alt":[],"source":"krupnik","glosses":[{"text":"sulphur","label":""}],"html":"<p>גפרית sulphur  תרג׳ ברא׳ י״ט כ״ד (גפרית): גפריתא (בהוצ׳ אח׳ ובתרג׳ ירוש׳ גופריתא).</p>","notation":["נ׳"]},"35304":{"h":"גּוּפְתָא","r":"KRU03895","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ סוכ׳ ב׳ נ״ג ע״א: גופתא.</p>","notation":[]},"35305":{"h":"גּוּפְתָּיָיה","r":"KRU03896","alt":[],"source":"krupnik","glosses":[{"text":"of Gufta","label":""}],"html":"<p>מגופתא of Gufta  ירוש׳ שבת ה׳ ז׳ ע״ב: חנין מגופתייה (צ״ל: גופתייה).</p>","notation":[]},"35306":{"h":"גּוּץ","r":"KRU03897","alt":[],"source":"krupnik","glosses":[{"text":"to gnaw (of mice)","label":""}],"html":"<p>כירסם to gnaw (of mice)  הור׳ י״ג ע״א: אפילו גגמי גייצי.</p>","notation":["פ״י"]},"35307":{"h":"גּוּץ²","r":"KRU03898","alt":["גּוּצָא"],"source":"krupnik","glosses":[{"text":"short, dwarfish","label":""}],"html":"<p>קצר הקומה short, dwarfish  ברכ׳ ל״א ע״א: לא ארוך ולא גוץ ולא קטן ולא אלם; ב״מ נ״ט ע״א: איתתך גוצא גחון ותלחש לה (משל).</p>","notation":["ז׳"]},"35308":{"h":"גּוּר","r":"KRU03900","alt":[],"source":"krupnik","glosses":[{"text":"to make a proselyte","label":"גִּיּיֵר פיעל,"},{"text":"to become a proselyte","label":"הִתְגַּיּיֵר התפ׳,"}],"html":"<p>גִּיּיֵר פיעל, הביא בברית היהדות to make a proselyte  שבת ל״א ע״א: גיירני.\nהִתְגַּיּיֵר התפ׳, התיהד to become a proselyte  ברכ׳ נ״ז ע״ב: עתידים להתגייר.</p>","notation":["Marked biblical in source"]},"35309":{"h":"גּוּר²","r":"KRU03901","alt":[],"source":"krupnik","glosses":[{"text":"to be a stranger, to sojourn","label":""},{"text":"to reside as a stranger","label":""}],"html":"<p>שהה במקום זר to be a stranger, to sojourn  תענ׳ כ״ה ע״א: גרי בך גירי. גַּיּיֵר פַעל, כנ״ל פיעל. שבת ל״א ע״א: גייריה. אִתְגַּיּיֵר אתפ׳, 1) כנ״ל. תרג׳ תהל׳ ס״ח י״ט: די מתגירין. 2) שהה במקום זר to reside as a stranger  תרג׳ ויק׳ ט״ז כ״ז (והגר הגר): וגיורי דיתגירון. </p>","notation":["Marked biblical in source"]},"35310":{"h":"גּוּר³","r":"KRU03902","alt":[],"source":"krupnik","glosses":[{"text":"to seduce","label":""}],"html":"<p>נאף to seduce  תרג׳ איוב ל״ו כ׳: לא תגייר אתת חברך (בכ״י: תגור).</p>","notation":["פיו״ע"]},"35311":{"h":"גּוּר גּוּרָא","r":"KRU03904","alt":[],"source":"krupnik","glosses":[{"text":"whelp","label":""}],"html":"<p>בן חיה יונק whelp  ויק״ר י״ט: מתלא אמר גור טב מכלב ביש; שם ל״א: עלה גורא אחד לארץ ישראל.</p>","notation":["ז׳","Marked biblical in source"]}};
